/* The Quant Hardwood — docs: the glossary (#/glossary, #/glossary/<key>, #/glossary/g:<group>)
 * and the methodology document (#/methodology, #/methodology/<section>).
 *
 * The glossary reads data/glossary.json ({groups: [{name, entries: [{key, label, desc,
 * fmt, lower, scope, kind}]}], model: [{key, label, group, desc}]}); until that is
 * published it is assembled from the league's player and team catalogues.
 * The methodology is static text: every constant in it was read from the Python under
 * oddsmarkets/basketball/ (each paragraph names its source file). */
(function (HW) {
'use strict';

const FX = () => HW.fx;
const esc = s => HW.esc(s);
const muted = t => HW.muted(t);

// ── glossary ───────────────────────────────────────────────────────────────

function slug(s) { return String(s || 'group').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }

function loadGlossary() {
  return HW.load('glossary.json').then(g => {
    // team metrics the site no longer shows (the rating's own uncertainty; the market title price) stay out of the glossary
    const hide = e => e && e.kind === 'team' && HW.ui && HW.ui.HIDE_TEAM && HW.ui.HIDE_TEAM[e.key];
    if (g && g.ok !== false && (g.groups || []).length) return Object.assign({ source: 'payload' }, g, { groups: g.groups.map(x => Object.assign({}, x, { entries: (x.entries || []).filter(e => !hide(e)) })) });
    const L = (HW.state && HW.state.league) || 'nba';
    const S = HW.currentSeason ? HW.currentSeason(L) : null;
    return HW.loadAll([L + '/' + S + '/players.json', L + '/' + S + '/teams.json']).then(res => {
      const groups = [];
      [[res[0], 'Player: ', 'player'], [res[1], 'Team: ', 'team']].forEach(p => {
        ((p[0] || {}).metrics || []).forEach(m => {
          const name = p[1] + (m.group || 'Other');
          let grp = groups.find(x => x.name === name);
          if (!grp) { grp = { name: name, entries: [] }; groups.push(grp); }
          grp.entries.push(Object.assign({ kind: p[2] }, m));
        });
      });
      return { groups: groups, model: [], source: 'catalogue' };
    });
  });
}

function fmtHint(e) {
  const tags = [];
  const f = e.fmt;
  if (f === 'pct') tags.push(['rate', '']);
  else if (f === 'prob') tags.push(['probability', '']);
  else if (f === 'int') tags.push(['count', '']);
  else if (f === 'pm') tags.push(['plus-minus', '']);
  else if (f === 'sec') tags.push(['time', '']);
  if (e.kind) tags.push([String(e.kind), 'kind']);
  if (e.lower) tags.push(['lower is better', 'lower']);
  if (e.scope === 'pbp') tags.push(['play-by-play, ~2017 on', 'pbp']);
  else if (e.scope && e.scope !== 'all') tags.push([String(e.scope), '']);
  return tags.map(t => '<span class="gl-tag' + (t[1] ? ' ' + t[1] : '') + '">' + esc(t[0]) + '</span>').join('');
}

function entryHTML(e, isModel) {
  const q = [e.label, e.key, e.desc, e.group, e.kind, isModel ? 'model' : ''].join(' ').toLowerCase();
  return '<div class="gl-entry" id="gl-' + esc(e.key) + '" data-q="' + esc(q) + '">' +
    '<dt><span>' + esc(e.label || e.key) + ' <a class="doc-anchor" href="#/glossary/' + encodeURIComponent(e.key) + '" title="Link to this entry">#</a></span>' +
    '<span class="gl-tags">' + (isModel ? '<span class="gl-tag model">model</span>' : fmtHint(e)) + '</span></dt>' +
    '<dd>' + (e.desc ? esc(e.desc) : '<span class="muted-inline">No definition yet.</span>') + '</dd></div>';
}

function renderGlossary(el, params) {
  const key = (params.rest || [])[0] || (params.query || {}).k || '';
  el.innerHTML = '<div id="glossary-root">' + muted('Loading the glossary…') + '</div>';
  return loadGlossary().then(g => {
    const root = document.getElementById('glossary-root');
    if (!root || !el.isConnected) return;
    const groups = g.groups || [];
    const modelGroups = [];
    (g.model || []).forEach(t => {
      const name = t.group || 'Model';
      let grp = modelGroups.find(x => x.name === name);
      if (!grp) { grp = { name: name, entries: [] }; modelGroups.push(grp); }
      grp.entries.push(t);
    });
    const nMetrics = groups.reduce((s, x) => s + (x.entries || []).length, 0);
    const nModel = modelGroups.reduce((s, x) => s + x.entries.length, 0);
    if (!nMetrics && !nModel) { root.innerHTML = HW.card('Glossary', '', HW.notBuilt('The glossary', null)); return; }
    const kinds = Array.from(new Set([].concat.apply([], groups.map(x => (x.entries || []).map(e => e.kind).filter(Boolean)))));
    const index = groups.map(x => '<a href="#/glossary/g:' + esc(slug(x.name)) + '" data-group="' + esc(slug(x.name)) + '">' + esc(x.name) + '</a>').join('') +
      modelGroups.map(x => '<a href="#/glossary/g:model-' + esc(slug(x.name)) + '" data-group="model-' + esc(slug(x.name)) + '">' + esc(x.name) + '</a>').join('');
    const cardOf = (name, sl, entries, isModel) => '<div class="card gl-group" data-group="' + esc(sl) + '"><div class="card-header">' + esc(name) + ' <span class="card-sub">' + entries.length + '</span></div><dl class="gl-list">' + entries.map(e => entryHTML(e, isModel)).join('') + '</dl></div>';
    root.innerHTML =
      '<div class="card"><div class="card-header">Glossary <span class="card-sub">Every metric the site computes for players, teams and lineups, and every model term it uses. How they are computed is in the <a href="#/methodology">methodology</a>.</span></div>' +
      '<div class="gl-top"><input id="gl-search" type="search" placeholder="Filter the glossary…" autocomplete="off" spellcheck="false">' +
      (kinds.length > 1 ? '<select id="gl-kind" class="hf-gl-kind"><option value="">all kinds</option>' + kinds.map(k => '<option value="' + esc(k) + '">' + esc(k) + '</option>').join('') + '<option value="model">model terms</option></select>' : '') +
      '<span class="gl-count" id="gl-count"></span></div>' +
      '<div class="gl-index">' + index + '</div>' +
      '<div class="doc-meta">' + nMetrics + ' metrics in ' + groups.length + ' groups' + (nModel ? ' and ' + nModel + ' model terms' : '') + (g.updated_at ? ' · updated ' + esc(HW.fmtStamp(g.updated_at)) : '') +
      (g.source === 'catalogue' ? ' · assembled from the ' + esc(String((HW.state || {}).league || 'nba').toUpperCase()) + ' player and team catalogues until data/glossary.json is published' : '') + '</div></div>' +
      groups.map(x => cardOf(x.name, slug(x.name), x.entries || [], false)).join('') +
      modelGroups.map(x => cardOf('Model terms: ' + x.name, 'model-' + slug(x.name), x.entries, true)).join('') +
      '<div class="card gl-empty" id="gl-none" style="display:none">Nothing in the glossary matches that.</div>';
    const input = document.getElementById('gl-search');
    const kindSel = document.getElementById('gl-kind');
    const count = document.getElementById('gl-count');
    const entries = Array.prototype.slice.call(root.querySelectorAll('.gl-entry'));
    const cards = Array.prototype.slice.call(root.querySelectorAll('.gl-group'));
    const total = entries.length;
    const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    const filter = () => {
      const needle = norm(input.value.trim()), kind = kindSel ? kindSel.value : '';
      let shown = 0;
      entries.forEach(e => {
        const q = e.dataset.q;
        const hit = (!needle || norm(q).indexOf(needle) >= 0) && (!kind || (' ' + q + ' ').indexOf(' ' + kind + ' ') >= 0);
        e.classList.toggle('hidden', !hit); if (hit) shown++;
      });
      cards.forEach(c => c.classList.toggle('hidden', !c.querySelector('.gl-entry:not(.hidden)')));
      document.getElementById('gl-none').style.display = shown ? 'none' : '';
      count.textContent = needle || kind ? shown + ' of ' + total + ' entries' : total + ' entries';
    };
    input.addEventListener('input', filter);
    input.addEventListener('keydown', ev => { if (ev.key === 'Escape') { input.value = ''; filter(); } });
    if (kindSel) kindSel.addEventListener('change', filter);
    filter();
    root.querySelectorAll('.gl-index a').forEach(a => a.addEventListener('click', ev => {
      ev.preventDefault();
      const grp = root.querySelector('.gl-group[data-group="' + a.dataset.group + '"]');
      if (grp) { grp.classList.remove('hidden'); grp.scrollIntoView({ block: 'start' }); }
      history.replaceState(null, '', a.getAttribute('href'));
    }));
    if (key) {
      if (key.indexOf('g:') === 0) {
        const grp = root.querySelector('.gl-group[data-group="' + key.slice(2).replace(/"/g, '') + '"]');
        if (grp) setTimeout(() => grp.scrollIntoView({ block: 'start' }), 0);
      } else {
        const e = document.getElementById('gl-' + key);
        if (e) { e.classList.add('hit'); setTimeout(() => e.scrollIntoView({ block: 'center' }), 50); setTimeout(() => e.scrollIntoView({ block: 'center' }), 400); }
        else { input.value = key; filter(); }
      }
    }
  });
}

// ── methodology ────────────────────────────────────────────────────────────

const METHOD_HTML = "<section id=\"m-data\">\n<h2>Data sources and refresh</h2>\n<p>Everything on the site starts from ESPN's public JSON services, which need no key and state no rate limit. They provide schedules, results, box scores, play-by-play with shot coordinates, ESPN's own per-play win probability, the DraftKings line ESPN displays (pickcenter), injuries, rosters and standings. Prediction-market numbers come from Kalshi and Polymarket. Nothing is taken from nba.com, wnba.com or Basketball-Reference.</p>\n\n<h3>ESPN endpoints</h3>\n<ul>\n<li><code>site.api.espn.com/apis/site/v2/sports/basketball/&lt;league&gt;/scoreboard?dates=YYYYMMDD</code>: one day per call, because a multi-day range answers with something that is not JSON. The answer's <code>leagues[0].calendar</code> lists the season's game days, which the fetcher uses as a whitelist of days to scan.</li>\n<li><code>.../summary?event=&lt;id&gt;</code>: one game: header, box score, plays, per-play win probability, pickcenter, injuries and series.</li>\n<li><code>.../teams</code>, <code>.../teams/&lt;id&gt;/roster</code> and <code>.../injuries</code>.</li>\n<li><code>site.api.espn.com/apis/v2/sports/basketball/&lt;league&gt;/standings?season=Y&amp;level=3</code>: the conferences and (NBA) divisions of any season.</li>\n<li><code>sports.core.api.espn.com/v2/sports/basketball/leagues/&lt;league&gt;/seasons/Y[/types/N]</code>: the start and end dates of a season and of its pre-season (type 1), regular season (2), postseason (3) and play-in (5). The core API lists seasons much further back than the box scores go, but the code uses it only for these dates. Nothing before 1997 is fetched.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/sources/espn.py</span>\n\n<h3>The client</h3>\n<p>Every ESPN call goes through one client. It spaces calls <code>interval</code> = 0.5 s apart (two a second), tries each call up to <code>retries</code> = 4 times, and counts every attempt against a <code>budget</code> (2,000 by default). After a network error it waits 3 s times the attempt number. After HTTP 429 or any 5xx it waits for the Retry-After header, or 10 s times the attempt number when the header is missing. Any other non-200 status, or an answer that is not a JSON object, is logged and returns nothing, so one bad game never stops a run. Reaching the budget raises <code>BudgetExhausted</code>, which stops a backfill cleanly so the next run resumes where it stopped. Requests time out after 30 s and identify themselves with a User-Agent naming the site.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td><code>Client.interval</code></td><td>0.5 s between calls</td></tr>\n<tr><td><code>Client.retries</code></td><td>4 attempts</td></tr>\n<tr><td><code>Client.budget</code></td><td>2,000 calls (overridden per run by <code>--budget</code>)</td></tr>\n<tr><td><code>TIMEOUT</code></td><td>30 s</td></tr>\n<tr><td><code>MIN_PBP_PLAYS</code></td><td>50 plays other than period start/end and game end; fewer means the game has no real play-by-play</td></tr>\n<tr><td><code>NO_COORD</code></td><td>-1,000,000: ESPN writes about -2.1e8 for a play without a location; anything below this is dropped</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/sources/espn.py</span>\n\n<h3>The game record</h3>\n<p>Each game is stored as one compact record: id, tip-off time (UTC), status (pre, in, post, postponed, canceled), season type, neutral-site flag, home and away team ids, the score, the number of periods, the line score by period, a box score per team, the odds, injuries, venue, attendance, the playoff series and a play-by-play flag. Rules applied while compacting:</p>\n<ul>\n<li>Box minutes are stored as seconds, but ESPN gives whole minutes, so every player's playing time is rounded to the minute.</li>\n<li>The team line's counting stats are the sums of the players' rows, because ESPN's own team line is shifted by a column in 2017-18 (assists, steals and blocks). Team turnovers are ESPN's <code>totalTurnovers</code> (team turnovers included); <code>team_tov</code> is that total minus the players' turnovers. Points in the paint, fast-break points, points off turnovers, largest lead and lead changes are ESPN's own; a value ESPN writes as -1 is stored as null.</li>\n<li>Plus-minus is stored as null when every player in the game has 0 or none, which is the case before about 2007.</li>\n<li>Injuries are kept only for games that are not yet final, because the summary lists today's injuries, not those on the game's date.</li>\n<li>The odds come from pickcenter: the DraftKings entry if there is one, else the first provider. The home spread is made negative when the home side is the favourite, using ESPN's favourite flags. The total and both moneylines are kept as given.</li>\n<li>A game has play-by-play when it carries at least 50 plays other than period starts, period ends and game end.</li>\n<li>All-Star games, Rising Stars and celebrity games are not stored.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/sources/espn.py</span><span class=\"src\">oddsmarkets/basketball/CONTRACT.md</span>\n<p>Raw play-by-play is stored separately, one gzipped file per game at <code>data/basketball/pbp/&lt;league&gt;/&lt;season&gt;/&lt;id&gt;.json.gz</code>, and is not committed to git. Each play is a row of sequence number, period, clock (seconds left in the period), ESPN type id, team id, participant ids, x and y (only on shooting plays with a location), score value, shooting and scoring flags, the running home and away scores, the play text and ESPN's points-attempted field. ESPN's per-play home win probability is kept beside the rows, keyed by sequence number. Substitution participants are [entering, leaving]; an assisted make lists [shooter, assister], a blocked miss [shooter, blocker] and a steal [player who lost the ball, stealer].</p>\n<span class=\"src\">oddsmarkets/basketball/sources/espn.py</span><span class=\"src\">oddsmarkets/basketball/CONTRACT.md</span>\n\n<h3>Fetching</h3>\n<p>The fetch script fills one store per league and season in two phases, newest season first:</p>\n<ul>\n<li><code>schedule</code>: one scoreboard call on a probe day inside the season (15 January for the NBA, 15 July for the WNBA) reads the season's calendar of game days. Then one scoreboard per game day gives every game's skeleton: teams, date, status, score and line score. If ESPN returns no calendar, a generous fixed window for the season is scanned instead. A standings call adds conferences and divisions when the store has none, and again on Mondays in the hourly mode.</li>\n<li><code>games</code>: one summary per finished game gives the box score, odds, series, venue and play-by-play. The game record goes into the store, and the play-by-play is written to its own file.</li>\n</ul>\n<p>Days already scanned and games already fetched as final are skipped, so a stopped run resumes where it left off. In the hourly mode (<code>--refresh-current</code>) the script works only on the current season. It re-scans the days from two days ago to a week ahead, and re-fetches games that finished in the last 48 hours if their last fetch is more than 6 hours old, to pick up late stat corrections. It also fetches games in progress, and the summaries of games starting in the next 36 hours, for their lines and injuries. The scheduled workflow that will run this mode is not in the repository at the time of writing, so the site's refresh cadence is not stated here.</p>\n<span class=\"src\">scripts/bb_fetch.py</span>\n<p>A second script turns the raw play-by-play into the committed model inputs for each season: <code>shots.json</code> (the shot table), <code>stints.json</code> (lineup stints) and <code>recon.json</code> (the per-game reconciliation report). It re-parses only games whose fetch time or the derivation version (currently 1) has changed. It keeps the rows of every other game, including games whose raw play-by-play is not on the machine running it, so history never drops out of the derived files.</p>\n<span class=\"src\">scripts/bb_derive.py</span>\n\n<h3>Stores</h3>\n<p>Each league and season has one store at <code>docs/hardwood/data/&lt;league&gt;/&lt;season&gt;/store.json</code>, which is the single source of truth for the models. It holds the teams (name, abbreviation, location, colours, conference, division), the players (name, short name, position, position pool, jersey, date of birth, teams), the games keyed by id, and fetch metadata: when each game was fetched, the date through which every game is final and fetched, the calendar and the days scanned. Stores are written to a temporary file and renamed into place, so a reader never sees a half-written store. When a game is fetched again, a poorer record never wipes a richer one: a scoreboard skeleton keeps the box score, injuries, line score, odds, venue, series and play-by-play flag already stored, and a rescan labelled \"reg\" does not overwrite a Cup, play-in or playoff label from the summary.</p>\n<span class=\"src\">oddsmarkets/basketball/store.py</span>\n</section>\n\n<section id=\"m-identity\">\n<h2>Identity, seasons and the clock</h2>\n<p>Teams, players and games are keyed by ESPN ids, stored as strings. ESPN keeps one id per franchise through relocations and renames (the Seattle SuperSonics and the Oklahoma City Thunder share id 25), and each season's scoreboards and box scores carry that era's name and abbreviation. Each season store therefore records the names of its own time. A franchise table documents the moves for display: for example the New Jersey Nets became the Brooklyn Nets in 2013, the Vancouver Grizzlies became the Memphis Grizzlies in 2002, the Utah Starzz became the San Antonio Silver Stars in 2003 and the Las Vegas Aces in 2018, and the WNBA added the Golden State Valkyries in 2025 and the Toronto Tempo and Portland Fire in 2026.</p>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span>\n<h3>Seasons</h3>\n<p>A season is labelled by the year it ends in, which is ESPN's <code>season.year</code>: the NBA's 2026-27 season is 2027, and the WNBA's 2026 season is 2026. The NBA season in play turns over in September and the WNBA's in April. A game's calendar day is its UTC tip-off time minus 6 hours, so a 7:30 pm Eastern game is not counted on the following day.</p>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span><span class=\"src\">oddsmarkets/basketball/models/_games.py</span>\n<h3>Season types</h3>\n<p>ESPN's season-type ids map to pre-season (1), regular season (2), postseason (3) and play-in (5). The event's note headline overrides this: an All-Star, Rising Stars or celebrity game is \"allstar\", and a Cup championship or final (not a semi-final) is \"cup\". ESPN files the NBA Cup's group and knockout games as regular-season games, which count in the standings. Only the Cup final is labelled \"cup\", and it does not count, which is the NBA's rule. The WNBA Commissioner's Cup final is handled the same way, through the summary's game note.</p>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span><span class=\"src\">oddsmarkets/basketball/sources/espn.py</span>\n<h3>Clock</h3>\n<div class=\"eq\">t = period_start(period) + period_len(period) - clock_s\nperiod_len = 720 s (NBA quarter), 600 s (WNBA quarter from 2006), 1200 s (WNBA half, 1997-2005), 300 s (any overtime)</div>\n<p><code>clock_s</code> is the time left in the period and <code>t</code> the elapsed game time in seconds. Regulation is 2,880 s in the NBA and 2,400 s in the WNBA.</p>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span>\n<h3>Position pools</h3>\n<p>ESPN's position abbreviation maps to one of three pools, used for percentiles, regression to the mean in projections, and the box-impact model. Wings and stretch bigs go to F.</p>\n<table class=\"tbl\"><thead><tr><th>ESPN position</th><th>Pool</th></tr></thead><tbody>\n<tr><td>G, PG, SG</td><td>G</td></tr>\n<tr><td>F, SF, PF, G-F, F-G, GF, FG, F-C, FC</td><td>F</td></tr>\n<tr><td>C, C-F, CF</td><td>C</td></tr>\n</tbody></table>\n<p>Any other text falls back on \"Guard\", \"Forward\" or \"Center\", then on the first letter. A player with no pool is treated as F by the impact and projection models.</p>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span><span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n</section>\n\n<section id=\"m-coverage\">\n<h2>Coverage</h2>\n<p>Box scores start in 1997 for both leagues: the NBA's 1996-97 season and the WNBA's first season. Play-by-play with shot coordinates starts around 2017. In the NBA, 2016-17 is patchy and 2018 onwards is complete. Before that, ESPN returns a single \"Start Period\" row for a game, so the game has no play-by-play.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>BOX_FROM</code> (first season with box scores)</td><td>1997</td><td>1997</td></tr>\n<tr><td><code>PBP_FROM</code> (first season with play-by-play)</td><td>2017</td><td>2017</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span>\n<h3>What exists only with play-by-play</h3>\n<p>Everything that needs to know who was on the floor, where a shot came from or how the score moved within a game is built from play-by-play. For a game without it, these are null: the scoring flow, win probability, shots and shot quality, lineups, the rotation chart, the play list and the per-game awards that depend on them. At the season level, a box-only season has:</p>\n<ul>\n<li>no RAPM. A player's HPM is then the box impact from the model's \"box\" variant, with the box model's residual standard deviation as its uncertainty;</li>\n<li>no shot-quality (xPTS) numbers and no shot features in the box-impact model;</li>\n<li>no WPA, clutch WPA or Clutch Player race;</li>\n<li>no lineup, on/off or stint-based metrics. Catalogue metrics with scope \"pbp\" are null.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/PAYLOADS.md</span><span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n<h3>Other gaps by era</h3>\n<ul>\n<li>Plus-minus is null before about 2007, and points in the paint are null where ESPN writes -1.</li>\n<li>In 2017-18 ESPN's scoring plays can carry a score value of 0, and its running scores can lag or lead. The parser fills the points from the attempt value and rebuilds the running score from the events themselves.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/sources/espn.py</span><span class=\"src\">oddsmarkets/basketball/pbp.py</span>\n<h3>WNBA specifics</h3>\n<ul>\n<li>Games were two 20-minute halves from 1997 to 2005, and have been four 10-minute quarters since 2006. Overtime is 5 minutes.</li>\n<li>The three-point arc was 20.5 ft (corners included) before 2013, and has been 22.15 ft, with 22 ft in the corners, since. The NBA arc is 23.75 ft, with 22 ft in the corners.</li>\n<li>Since 2016 the eight playoff teams are seeded by league rather than by conference.</li>\n<li>The 2026 league has 15 teams (East 7, West 8) and 44 games each. Earlier team counts and game counts are in the format table but are marked unverified.</li>\n<li>No WNBA arena is treated as being at altitude, the WNBA has no play-in, and the WNBA draft lottery is not modelled. There is no WNBA Clutch Player award.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/canon.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n<h3>Models that need history</h3>\n<p>Several fitted quantities fall back to documented defaults until enough seasons are on disk:</p>\n<ul>\n<li>the season-to-season carry-over of team ratings needs 40 team-season pairs;</li>\n<li>the game-model coefficients need 200 games, and the market's standard deviation 100 games with a line;</li>\n<li>the award weights need three past seasons whose winner is in the candidate pool.</li>\n</ul>\n<p>Each is noted in its section below.</p>\n</section>\n\n<section id=\"m-pbp\">\n<h2>Play-by-play processing</h2>\n<p>ESPN's play-by-play has no on-floor lineups, no possession markers and no shot distance or zone. All three are rebuilt here, and each game is checked against its box score.</p>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span>\n\n<h3>Events</h3>\n<p>Each play is classified as one of: substitution, free throw, shot, rebound, turnover, timeout, jump ball, period start, period end or other. The classifier uses ESPN's type id first and the play text second:</p>\n<ul>\n<li>Substitutions are type 584 (\"X enters the game for Y\").</li>\n<li>Free throws are read from the text \"free throw n of m\". The text also says whether the free throw is technical, flagrant or clear-path.</li>\n<li>Shots are a list of ESPN shot-type ids, or any shooting play attempting 2 or 3 points.</li>\n<li>Rebounds are types 155 (defensive) and 156 (offensive), or \"rebound\" in the text.</li>\n<li>Turnovers are types 61 to 91, or \"turnover\" or \"traveling\" in the text. A turnover is a steal when the text says so.</li>\n<li>Timeouts are types 16 to 20, and jump balls types 11 and 615.</li>\n<li>Fouls are found in the text, and flagged as technical, flagrant, offensive (including charges) or shooting.</li>\n</ul>\n<p>A shot's value is ESPN's points-attempted field. When that is missing, a shot is a three if the text says \"three point\" and a two otherwise.</p>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span>\n\n<h3>Lineups</h3>\n<p>The five players on the floor for each team at every event are rebuilt as follows:</p>\n<ul>\n<li>Period 1 starts with the box-score starters.</li>\n<li>Each later period's opening five is inferred, in this order:\n<ul>\n<li>players whose first appearance in the period is being subbed out;</li>\n<li>then players who act before any substitution involving them (on a shot, rebound, turnover, jump ball, or a non-technical free throw or foul);</li>\n<li>topped up from the previous period's closing five, leaving out anyone who is subbed in during the period;</li>\n<li>in the rare case that is still short, the team's highest-minute players who are not known to have come in.</li>\n</ul></li>\n<li>If more than five qualify, the players subbed out come first, and the others are ranked by how often they act.</li>\n<li>Substitutions are then applied in order. Changes made at a period break are logged at the new period's opening clock.</li>\n</ul>\n<p>Three kinds of repair are made and counted as \"fixes\":</p>\n<ul>\n<li>A substitution whose incoming player is already on the floor removes the outgoing player.</li>\n<li>A substitution whose outgoing player is not on the floor removes the most plausible absentee instead.</li>\n<li>A player who acts while not on the floor is put on, replacing the most plausible absentee. Actions logged at the same clock as the player's own substitution are ignored, because ESPN's order of events there is unreliable.</li>\n</ul>\n<p>The most plausible absentee is the first on-floor player whose next appearance is being subbed in. If there is none, it is a player who never acts again, and failing that the player who goes longest without acting.</p>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span>\n\n<h3>Possessions</h3>\n<p>A possession belongs to one team and ends in one of these ways:</p>\n<ul>\n<li>a made field goal (<code>made</code>), held open until the next significant event in case it is an and-one;</li>\n<li>a defensive rebound (<code>dreb</code>);</li>\n<li>a turnover (<code>tov</code>);</li>\n<li>a made last free throw (<code>ft</code>);</li>\n<li>the end of the period (<code>period</code>);</li>\n<li><code>other</code>: a held ball won by the defence, or an inconsistency in the data.</li>\n</ul>\n<p>An offensive rebound continues the same possession, so a possession never starts with one. Each possession records how it started: after a defensive rebound by a player or a steal (<code>tr</code>, a live-ball start), after a made basket or made last free throw (<code>made</code>), after any other dead ball (<code>dead</code>), or at the start of a period (<code>period</code>). It also records its start and end times, its points, and the five players at each end.</p>\n<p>Special cases:</p>\n<ul>\n<li>A made shot followed by a non-technical free throw by the same team, in the same period and within 0.05 s on the clock, is an and-one. The possession ends with the free throw.</li>\n<li>Technical free throws never change possession.</li>\n<li>Flagrant and clear-path free throws keep the ball for the shooting team, and so does a lone free throw (1 of 1) that is not an and-one, as after a take foul or an away-from-the-play foul.</li>\n<li>A \"defensive\" rebound credited to the team already on offence is one of ESPN's dead-ball team rebounds, and it does not end the possession.</li>\n<li>When a held ball has already moved the ball and ESPN then logs the loser's turnover, the turnover is booked on the possession the held ball ended.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span><span class=\"src\">oddsmarkets/basketball/CONTRACT.md</span>\n\n<h3>Stints</h3>\n<p>A stint is a stretch in one period with the same ten players on the floor. Points, field-goal attempts, free-throw attempts, turnovers and offensive rebounds by a player go to the stint that holds the event. A possession counts in the stint holding its last event. A stint's time runs from its first event to the next lineup change; the first stint of a period starts at the period's start, and the last runs to the period's end. Stints without exactly five players a side are left out of <code>stints.json</code>, and so out of RAPM.</p>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span>\n\n<h3>Checks against the box score</h3>\n<ul>\n<li>Minutes: each player's time on the floor, summed over stints, is compared with the player's box-score time. ESPN's box minutes are whole minutes, so up to 30 s of any difference is rounding. A game passes when no player is off by more than <code>RECON_TOL_S</code> = 60 s. The report also gives the seconds played with a five that is not complete.</li>\n<li>Points: the points summed from scoring events must equal the final score exactly.</li>\n<li>Three-pointers: the share of shots whose coordinates fall on the same side of the three-point line as ESPN's points-attempted value, with a tolerance of 0.5 ft.</li>\n<li>Possessions: the season summary reports the share of games whose two teams' possession counts are within 2 of each other, the median and 95th percentile of each game's largest minutes error, and the mean number of lineup fixes.</li>\n</ul>\n<p>At the time of writing, the derived WNBA 2026 season (266 games with play-by-play) had every game within 60 s and every game's points exact. The median of each game's largest minutes error was 29 s, the 95th percentile 30 s, three-point agreement 99.76%, possession counts within 2 in 98.9% of games, and no lineup fixes. These figures are recomputed whenever the season is derived again.</p>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span><span class=\"src\">scripts/bb_derive.py</span><span class=\"src\">docs/hardwood/data/wnba/2026/recon.json</span>\n\n<h3>Shot geometry</h3>\n<p>ESPN's shot coordinates are in whole feet on a half court: x runs from 0 to 50 across the floor with the rim at x = 25, and y runs along the floor from the shooting team's basket. The rim centre sits at y = 0.75, a value fitted on the distances written in the play text (\"N-foot\"), with a mean absolute error of 0.4 ft. The baseline sits near y = -4.5, and heaves from the far half reach y = 75. Each shot is converted to feet from the rim:</p>\n<div class=\"eq\">x_ft = x - 25        (across the floor, -25 .. 25)\ny_ft = y - 0.75      (along the floor, 0 at the rim)\ndist_ft = sqrt(x_ft^2 + y_ft^2)\nangle_deg = atan2(x_ft, y_ft)   (0 = straight on, +-90 = along the baseline)</div>\n<p>A shot without coordinates takes its distance from the play text when the text gives one. The zone follows ESPN's attempt value, and the geometry splits it further:</p>\n<table class=\"tbl\"><thead><tr><th>Zone</th><th>Rule</th></tr></thead><tbody>\n<tr><td><code>heave</code></td><td>a three attempted from more than 40 ft (<code>HEAVE_FT</code>)</td></tr>\n<tr><td><code>corner3</code></td><td>a three with y_ft ≤ 8.75 ft (<code>CORNER_Y_FT</code>, the straight corner segment) and |x_ft| ≥ 20 ft</td></tr>\n<tr><td><code>ab3</code></td><td>any other three (above the break)</td></tr>\n<tr><td><code>rim</code></td><td>a two from less than 4 ft</td></tr>\n<tr><td><code>paint</code></td><td>a two with |x_ft| ≤ 8 ft (<code>LANE_HALF_W_FT</code>, a 16 ft lane) and y_ft ≤ 13.75 ft (<code>FT_LINE_Y_FT</code>, the free-throw line)</td></tr>\n<tr><td><code>mid</code></td><td>any other two</td></tr>\n</tbody></table>\n<p>The straight corner line runs 14 ft from the baseline, which is 8.75 ft along the floor from the rim centre.</p>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span><span class=\"src\">oddsmarkets/basketball/canon.py</span>\n\n<h3>Shot attributes</h3>\n<ul>\n<li>Shot type is dunk, layup, tip, hook, floater, jumper, pull-up, step-back, fadeaway, turnaround or other. It comes from ESPN's type id where the id is known, and otherwise from keywords in the type text or play text. An alley-oop and a finger roll count as layups, and \"three point\" as a jumper.</li>\n<li>A shot is assisted when it is made and the text names an assist. The assister is the second participant.</li>\n<li>A shot is blocked when it is missed and the text says \"blocks\". A blocked shot is always a miss.</li>\n<li>A shot is a putback when it has one of ESPN's putback, tip or putback-dunk types (94, 125, 138, 150). It is also a putback when it comes within <code>PUTBACK_S</code> = 3 s of the same team's offensive rebound by a player, in the same period and possession.</li>\n<li>A shot is in transition when its possession started live (<code>tr</code>) and the shot comes within <code>TRANSITION_S</code> = 6 s of the possession's start.</li>\n<li>Each shot records the shooting team's margin before it.</li>\n<li>A shot is clutch when it comes in the fourth period or overtime with no more than 300 s on the clock and the margin within 5 points (<code>CLUTCH_S</code>, <code>CLUTCH_MARGIN</code>).</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/pbp.py</span>\n</section>\n\n<section id=\"m-ratings\">\n<h2>Team ratings</h2>\n<p>Team strength is measured per 100 possessions: offence (points scored), defence (points allowed, so lower is better), net (offence minus defence) and pace. A team's net rating is roughly how many points better than an average team it would be over 100 possessions on a neutral floor.</p>\n<h3>Possessions</h3>\n<div class=\"eq\">poss_team = FGA - OREB + TOV + 0.44 * FTA        (TOV includes team turnovers)\nposs_game = mean of the two teams' estimates (an estimate of 20 or fewer is ignored)\npace = poss_game * regulation seconds / seconds played    (per 48 minutes NBA, per 40 WNBA)</div>\n<p>A finished game without a box score is given possessions equal to the mean pace of the games that have one, scaled for overtime. Its score still counts, but it is left out of the pace fit.</p>\n<span class=\"src\">oddsmarkets/basketball/models/_games.py</span><span class=\"src\">oddsmarkets/basketball/models/ratings.py</span>\n\n<h3>Static fit</h3>\n<p>Every finished regular-season, Cup, play-in and playoff game gives two observations, one for each offence:</p>\n<div class=\"eq\">100 * pts_home / poss = mu + o_home + d_away + (h / 2) * [not neutral] + e\n100 * pts_away / poss = mu + o_away + d_home - (h / 2) * [not neutral] + e\nweight w = 0.5 ^ (age_days / half_life) * poss / mean(poss)\npenalty  = ridge * sum_i [ (o_i - o_i_prior)^2 + (d_i - d_i_prior)^2 ]  +  0.05^2 * h^2</div>\n<p>o_i is team i's offence above average, d_i its points allowed above average, and h the home-court effect per 100 possessions on the margin. Without a prior, the team effects shrink towards zero, which is the league mean. The ridge is measured in games: ridge = 8 means the prior counts like eight average games. A very weak penalty on h keeps it finite when every game is at a neutral site. The system is solved as one augmented sparse least-squares problem. The reported ratings are centred:</p>\n<div class=\"eq\">L = mu + mean(o) + mean(d)                       (league offensive rating)\noff_i = L + o_i - mean(o)\ndef_i = L + d_i - mean(d)\nnet_i = off_i - def_i\nse_net_i from the posterior covariance s^2 (A'WA + P)^-1,  s^2 = weighted residual variance\nhca_pts = h * league_pace / 100</div>\n<p>Pace is a separate ridge fit of each game's pace: pace_game = P + p_home + p_away, with the same decay weights and ridge. It is reported as pace_i = league pace + p_i - mean(p).</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>HALF_LIFE</code> (days)</td><td>75</td><td>45</td></tr>\n<tr><td><code>RIDGE</code> (games-equivalents)</td><td>8</td><td>6</td></tr>\n<tr><td>League ORtg before any fit (<code>GAME_DEFAULTS[\"ortg\"]</code>)</td><td>114.0</td><td>104.0</td></tr>\n<tr><td>League pace before any fit (<code>GAME_DEFAULTS[\"pace\"]</code>)</td><td>99.0</td><td>80.0</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/ratings.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n\n<h3>Preseason prior</h3>\n<p>Before a season's first game, and as the ridge centre during the season, each team starts from last season's full-season ratings (no time decay, ridge 2, at least 30 games) regressed towards the mean:</p>\n<div class=\"eq\">net_prior = b * net_last\noff_prior = L + b * (off_last - L),   def_prior = L + b * (def_last - L)\npace_prior = P + b_pace * (pace_last - P)\nse_prior = residual sd of the carry-over regression</div>\n<p>b is the least-squares slope through the origin of a team's net rating on its previous season's, fitted on every pair of consecutive seasons on disk. Both seasons must have at least 20 games, and the fit needs at least 40 pairs; otherwise the defaults below apply. b_pace is fitted in the same way on pace deviations from the league mean. A team new to the league (an expansion team) starts at net -4, with its offence 2 points below average and its defence 2 points worse, and its uncertainty is multiplied by 1.25.</p>\n<p>The prior can also blend in roster impact, the minutes-weighted sum of the current players' HPM (see Player impact), so that trades and free agency move it:</p>\n<div class=\"eq\">net = (1 - blend) * b * net_last + blend * (impact_t - mean impact)      blend = 0.5\nse  = se_prior * sqrt(1 - blend / 2)</div>\n<p>The change is split equally between offence and defence. The roster term is on for both leagues (since 2 October 2026). It is built from ESPN's current team rosters, refreshed daily: each player counts at the HPM projected to the new season over the projected minutes, the minutes go to the players with the most until five players' worth are used, and the rest, like every rookie, count at replacement level (-2). It applies to the current season only.</p>\n<p>It had been switched off for a day because, against the Kalshi NBA 2026-27 win totals, it widened the gap to the market (a mean difference in the probability of the over of 18 percentage points, against 15 with last season alone). That compared one season with a market, not with what happened. Tested walk-forward against outcomes, with each past season's preseason rosters, it is better than last season alone:</p>\n<table class=\"tbl\"><thead><tr><th>Error of the prior against the actual season net rating (RMSE)</th><th>Last season only</th><th>With the roster term</th><th>Seasons better</th></tr></thead><tbody>\n<tr><td>NBA 2012-2026 (450 team-seasons)</td><td>3.75</td><td>3.60</td><td>11 of 15</td></tr>\n<tr><td>WNBA 2010-2026 (193 team-seasons)</td><td>5.20</td><td>4.89</td><td>10 of 16</td></tr>\n</tbody></table>\n<p>It also lowers the log-loss of each team's first 20 or so games (NBA by 0.003, WNBA by 0.004). The site still does not show win-total differences from the market before the season starts, because rookies count at replacement level and single-season HPM is noisy for some stars.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>DEFAULT_B</code> (carry-over slope until fitted)</td><td>0.65</td><td>0.65</td></tr>\n<tr><td>Default pace carry-over</td><td>0.6</td><td>0.6</td></tr>\n<tr><td><code>DEFAULT_SE</code> (prior sd of net, until fitted)</td><td>4.0</td><td>5.0</td></tr>\n<tr><td><code>EXPANSION_NET</code></td><td>-4.0</td><td>-4.0</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/ratings.py</span>\n\n<h3>Rating paths</h3>\n<p>The rating after each game comes from a Kalman filter on the vector of all teams' net ratings, with the full covariance:</p>\n<div class=\"eq\">state:    n_t = n_(t-1) + u,   u ~ N(0, q * min(days since last game day, 60)) per team\nobserve:  100 * margin / poss - h * [not neutral] = n_home - n_away + e,   e ~ N(0, r)\nstart:    n_0 = prior net,  Var(n_0) = prior se_net^2  (5^2 when there is no prior)\nr = 0.8 * variance of the season's 100 * margin / poss   (160 with 30 games or fewer)\nh from a no-decay fit with ridge 4</div>\n<p>Each game updates both teams, and through the covariance every team whose rating is correlated with theirs. The path is the filtered estimate after each of the team's games, with its standard error.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>Q_PER_DAY</code> (random-walk variance per day)</td><td>0.03</td><td>0.05</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/ratings.py</span>\n</section>\n\n<section id=\"m-game\">\n<h2>Game model</h2>\n<p>A game's final home margin is modelled as Normal(mu, sigma), where mu is the expected margin from the two teams' ratings and the game's context.</p>\n<div class=\"eq\">mu = s * (net_h - net_a) * pace_g / 100                   rating difference, per game\n   + HCA * [not neutral]                                   home court\n   + b_b2b  * (b2b_h - b2b_a)                              second night of a back-to-back\n   + b_rest * (min(rest_h, 3) - min(rest_a, 3))            days off before the game, capped at 3\n   + b_trav * (km_h - km_a) / 1000                         distance from each team's previous venue\n   + b_tz   * (tz_h - tz_a)                                time-zone hours crossed since the previous game\n   + b_alt  * [host is DEN or UTA and not neutral]         altitude (NBA only)\n   + inj_h - inj_a                                         injuries (optional input)\n\npace_g = pace_h + pace_a - league_pace\np_home = Phi(mu / sigma),   spread_fair = -mu   (home spread, DraftKings sign: negative = home favoured)</div>\n<p>net and pace come from the team ratings as of the day before the game. A team without a rating is treated as average.</p>\n<span class=\"src\">oddsmarkets/basketball/models/game.py</span>\n\n<h3>Schedule context</h3>\n<p>For each team the model looks at its previous non-exhibition game:</p>\n<ul>\n<li>rest is the number of calendar days between the two games minus 1, and b2b is 1 when rest is 0;</li>\n<li>travel is the great-circle distance (Earth radius 6,371 km) from the previous game's arena to this one's;</li>\n<li>the time-zone term is the absolute difference in the two arenas' standard UTC offsets.</li>\n</ul>\n<p>Travel and time zones count only when rest is 3 days or fewer. A team's first game of the season counts as 3 days' rest, with no travel. Arenas are fixed coordinates by team abbreviation, with standard (not daylight-saving) offsets and altitude in metres. Denver (1,609 m) and Utah (1,288 m) are the NBA's altitude teams; the WNBA has none.</p>\n<span class=\"src\">oddsmarkets/basketball/models/game.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n\n<h3>Injuries</h3>\n<p>When a list of missing players is supplied (each with an impact per 100 possessions and the minutes the player would have played), the team loses:</p>\n<div class=\"eq\">inj_team = - sum_players (impact_p - replacement) * min(minutes_p, reg_minutes) / reg_minutes * pace_g / 100\nreg_minutes = 48 (NBA), 40 (WNBA);   replacement = GAME_DEFAULTS[\"replacement\"] = -2.0</div>\n<p>The model accepts this input, but the model code does not build the list itself. Whether a published forecast includes injuries depends on the site build, and its game page shows the injury term separately.</p>\n<span class=\"src\">oddsmarkets/basketball/models/game.py</span>\n\n<h3>Totals</h3>\n<div class=\"eq\">pts_h = (off_h + def_a - L + h / 2) * pace_g / 100 + context / 2\npts_a = (off_a + def_h - L - h / 2) * pace_g / 100 - context / 2\nraw   = pts_h + pts_a,   context = mu - rating term - HCA term\ntotal = total_a + total_b * raw + total_post * [playoff game]</div>\n<p>Here h is the home-court term in points, split equally between the two teams' scores, and context is the rest, travel, altitude and injury terms. The last line is a calibration added in model version 4 (2 October 2026): the ratings total ran about 2 points low in the NBA regular season and 3 to 10 points high in the playoffs, so the final total is regressed on the raw total and a playoff indicator over walk-forward history, and the difference is split equally between the two teams' points. Fitted: NBA 7.84 + 0.972 * raw - 5.77 in the playoffs (residual sd 18.2); WNBA -2.33 + 1.020 * raw - 0.39 (sd 16.7). Out of sample it lowers the NBA total's error (RMSE 18.65 to 18.56 on 2024-2026); in the WNBA it changes little.</p>\n<span class=\"src\">oddsmarkets/basketball/models/game.py</span>\n\n<h3>Fitting</h3>\n<p>The coefficients s (<code>rating_scale</code>), HCA, b_b2b, b_rest, b_trav, b_tz, b_alt and sigma are fitted on walk-forward history. For every finished game of every season on disk, the ratings are refitted weekly (<code>REFIT_DAYS</code> = 7) from games strictly before the start of that week, with the preseason prior. The observed margin is then regressed on [rating term, home indicator, b2b, rest, travel, time zones, altitude]:</p>\n<div class=\"eq\">beta  = (X'X + 1.0 * I)^-1 X'y        (columns that are always zero are dropped, e.g. altitude in the WNBA)\nsigma = sqrt( RSS / (n - k) )\nsigma_market = sqrt( mean( (margin + spread_home)^2 ) )   over games with a DraftKings line (needs 100)</div>\n<p>The fit needs at least 200 games. Until then, and for anything not fitted, the defaults below apply with s = 1 and an uncalibrated total. The fit (with the totals calibration) is run on the full history on the build machine and committed with the code (<code>models/fitted/</code>); the build reads a local fit of the current model version first, then the committed one, then the defaults.</p>\n<table class=\"tbl\"><thead><tr><th><code>GAME_DEFAULTS</code> key</th><th>Meaning</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>sigma</code></td><td>sd of the margin (points)</td><td>12.0</td><td>12.5</td></tr>\n<tr><td><code>hca</code></td><td>home court (points)</td><td>2.4</td><td>2.0</td></tr>\n<tr><td><code>b2b</code></td><td>per back-to-back difference</td><td>-1.6</td><td>-1.2</td></tr>\n<tr><td><code>rest</code></td><td>per day of rest difference</td><td>0.4</td><td>0.3</td></tr>\n<tr><td><code>travel_1000km</code></td><td>per 1,000 km difference</td><td>-0.25</td><td>-0.2</td></tr>\n<tr><td><code>tz</code></td><td>per time zone difference</td><td>-0.25</td><td>-0.2</td></tr>\n<tr><td><code>altitude</code></td><td>host at altitude</td><td>1.0</td><td>0.5 (no altitude teams)</td></tr>\n<tr><td><code>pace</code></td><td>league pace before any fit</td><td>99.0</td><td>80.0</td></tr>\n<tr><td><code>ortg</code></td><td>league ORtg before any fit</td><td>114.0</td><td>104.0</td></tr>\n<tr><td><code>replacement</code></td><td>impact of a replacement player (per 100)</td><td>-2.0</td><td>-2.0</td></tr>\n<tr><td><code>sigma_market</code></td><td>sd of margin around the spread</td><td>12.0</td><td>12.5</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/game.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n\n<h3>Market-informed model (NBA, since 21 October 2026)</h3>\n<p>In the NBA the published line comes from a second model. It adds two things the equation above ignores: what earlier games' closing lines say about each team, and who is likely to play. It is fitted to predict the closing spread, which is a less noisy target than the result:</p>\n<div class=\"eq\">mk     = h_m * [not neutral] + r_home - r_away      market ratings: weighted ridge on the closing spreads of games before\n                                                 the day (half-life 20 days, ridge 1; prior 0.6 x last season's final ratings)\nav_t   = (expected rotation strength - what the rating already reflects) x (1 - prior share)    availability, per 100\nmargin = 0.48 + 0.656 mk + 0.413 (net_h - net_a) pace_g / 100 + 0.905 (av_h - av_a) pace_g / 100\n         - 1.43 b2b + 0.10 rest + 0.41 altitude + 0.26 [not neutral] - 0.25\np_home = Phi(margin / 11.55)\ntotal  = fitted to closing totals: market total, ratings total, roster O/D change, rest, back-to-backs, playoffs, early season</div>\n<p>Availability: each player's recent minutes times the chance of playing, which depends on how many games in a row the player has missed (0.94 after playing, 0.62 after missing one, 0.37 after two, and so on), at last season's value (half RAPM, half box impact, shrunk towards replacement). Players listed Out on ESPN's injury report count as not playing. This replaces the separate injury adjustment, and it is the part that cannot be checked against history, because ESPN keeps no past injury reports. On the game page, \"Team ratings\" includes the market ratings and \"Injuries\" is the availability term.</p>\n<p>Tested walk-forward on NBA 2024-2026, 3,937 games, with every choice made on 2014-2023:</p>\n<ul>\n<li>log-loss 0.6043 to 0.5935 (paired difference -0.0108, 95% interval -0.0153 to -0.0065), about level with ESPN's opening line (0.5930) and still behind the close (0.5815). That is about half the gap to the close.</li>\n<li>Calibration slope 1.12 to 0.99.</li>\n<li>Total error (RMSE) 18.55 to 18.44.</li>\n</ul>\n<p>The model uses only the lines stored with past games. It falls back to the equation above when a season has too few stored lines (fewer than half its games after 50 games), and for past seasons' game pages. In the WNBA the gain was not significant on the test seasons (-0.0050, -0.0165 to +0.0067, 908 games), so the WNBA keeps the equation above. A better forecast of the closing line is not an advantage over it: in the betting backtest neither model beats ESPN's opening lines or Kalshi after costs.</p>\n<span class=\"src\">oddsmarkets/basketball/models/informed.py</span><span class=\"src\">oddsmarkets/basketball/research/improve.py</span><span class=\"src\">docs/research/basketball_edge.md</span>\n\n<h3>Converting a spread</h3>\n<p>A market spread becomes a win probability by p = Phi(-spread_home / sigma_market). The site uses this for the DraftKings line, in the backtest and as the last-resort market number.</p>\n<span class=\"src\">oddsmarkets/basketball/models/game.py</span>\n</section>\n\n<section id=\"m-season-sim\">\n<h2>Season simulation</h2>\n<p>The rest of the season is simulated 20,000 times: the remaining regular season, tiebreakers, the play-in, the playoffs and, for the NBA, the draft lottery. The simulations run vectorised in chunks of 5,000 (<code>CHUNK</code>).</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span>\n\n<h3>State</h3>\n<p>Results so far come from the store:</p>\n<ul>\n<li>Standings games are those labelled \"reg\", which includes the NBA Cup's group and knockout games. The Cup final, labelled \"cup\", does not count.</li>\n<li>Play-in and playoff games are the postseason. A play-in game or playoff game already played is fixed, and a series in progress continues from its current score.</li>\n<li>A game is unplayed if it is not final, or if it falls after the date the simulation runs through.</li>\n<li>Placeholder \"TBD\" teams are ignored.</li>\n<li>A postponed game is dropped when both teams already have a full schedule, since it was rescheduled under another id.</li>\n<li>Once the postseason has begun, any regular-season game still on the books is dropped.</li>\n</ul>\n<p>Before the NBA Cup knockout draw, each team has up to two \"TBD\" games. If a team has fewer standings games scheduled than the format's total, and no team is short by more than 4, the shortfall is filled with games between conference rivals that are short too. The home side of each filler game is drawn at random.</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span>\n\n<h3>Simulated games</h3>\n<div class=\"eq\">margin(s, g) = mu_g + (x_(s,h,w) - x_(s,a,w)) * P / 100 + sigma_n * eps\nx_(s,t,w)    = z_(s,t) + sum_(k &lt;= w) u_(s,t,k),   z ~ N(0, se_t^2),  u ~ N(0, drift^2)\nsigma_n      = sqrt( max( sigma^2 - mean(2 * se^2) * (P/100)^2 , (0.85 * sigma)^2 ) )</div>\n<p>mu_g is the game model's expected margin for that fixture, with ratings, home court, rest, travel and altitude. P is the league pace and w the week of the game, counted from the first remaining game day.</p>\n<p>z is a season-long draw of each team's rating error, scaled by the standard error from the ratings fit. A team that is better than its rating is therefore better in every remaining game, so the simulated outcomes are correlated. u is a weekly random walk that lets strength drift during the season.</p>\n<p>sigma was fitted on walk-forward residuals, which already contain rating error. The game-level noise sigma_n therefore removes the average rating variance, but it never falls below 85% of sigma.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td>Simulations (<code>n</code>)</td><td>20,000</td><td>20,000</td></tr>\n<tr><td><code>DRIFT</code> (weekly sd of the random walk, net per 100)</td><td>0.35</td><td>0.45</td></tr>\n<tr><td>Rating se when a team has none</td><td>4.0</td><td>4.0</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span>\n\n<h3>Ranking and tiebreakers</h3>\n<p>Teams are ranked by win percentage within their seeding group: the conference in the NBA, and the whole league in the WNBA (since 2016). An exact tie is broken by the format's two-team list or its multi-team list:</p>\n<ul>\n<li>Each criterion splits the tied teams into groups by value.</li>\n<li>Any group still tied restarts from the top of the appropriate list.</li>\n<li>A tie that survives every criterion is drawn at random.</li>\n</ul>\n<table class=\"tbl\"><thead><tr><th>Criterion</th><th>Meaning</th></tr></thead><tbody>\n<tr><td><code>h2h</code></td><td>win % in games among the tied teams</td></tr>\n<tr><td><code>div_winner</code></td><td>a division winner ranks ahead of a non-winner (division winners are decided first, by the same rules)</td></tr>\n<tr><td><code>div_record</code></td><td>division win %, only when all the tied teams share a division</td></tr>\n<tr><td><code>conf_record</code></td><td>conference win %</td></tr>\n<tr><td><code>vs_playoff_own</code></td><td>win % against own-conference teams at or above the win % of the 10th place (8th before the play-in), ties included</td></tr>\n<tr><td><code>vs_playoff_other</code></td><td>the same against the other conference</td></tr>\n<tr><td><code>vs_500</code></td><td>win % against teams finishing at .500 or better</td></tr>\n<tr><td><code>h2h_pd</code></td><td>point differential in games among the tied teams</td></tr>\n<tr><td><code>pd</code></td><td>point differential in all games</td></tr>\n</tbody></table>\n<table class=\"tbl\"><thead><tr><th>List</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td>Two teams (<code>NBA_TB_TWO</code>, <code>WNBA_TB_TWO</code>)</td><td>h2h, div_winner, div_record, conf_record, vs_playoff_own, vs_playoff_other, pd</td><td>h2h, vs_500, h2h_pd, pd</td></tr>\n<tr><td>Three or more (<code>NBA_TB_MULTI</code>, <code>WNBA_TB_MULTI</code>)</td><td>div_winner, h2h, div_record, conf_record, vs_playoff_own, pd</td><td>h2h, vs_500, h2h_pd, pd</td></tr>\n</tbody></table>\n<p>In simulated seasons, every simulated game counts towards each of these: wins, losses, conference and division records, head-to-head results, and point differentials (using the simulated margin).</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n\n<h3>Formats</h3>\n<p>The current seasons' formats, side by side:</p>\n<table class=\"tbl\"><thead><tr><th>Field</th><th>NBA 2027</th><th>WNBA 2026</th></tr></thead><tbody>\n<tr><td>Teams; games each</td><td>30; 82</td><td>15; 44</td></tr>\n<tr><td>Seeding group</td><td>conference (15 each)</td><td>league</td></tr>\n<tr><td>Direct playoff places per group</td><td>6</td><td>8</td></tr>\n<tr><td>Play-in</td><td>seeds 7 to 10</td><td>none</td></tr>\n<tr><td>Playoff teams per group</td><td>8</td><td>8</td></tr>\n<tr><td>Series lengths (best of)</td><td>7, 7, 7, 7</td><td>3, 5, 7</td></tr>\n<tr><td>Home patterns (H = higher seed at home)</td><td>HHAAHAH in every round (2-2-1-1-1)</td><td>HAH, HHAAH, HHAAHAH</td></tr>\n<tr><td>Rounds</td><td>first round, conference semi-finals, conference finals, Finals</td><td>first round, semi-finals, Finals</td></tr>\n<tr><td>Finals home court</td><td>better regular-season record (point differential on a tie)</td><td>higher seed</td></tr>\n<tr><td>Lottery</td><td>2019 table, 4 picks drawn</td><td>not modelled</td></tr>\n<tr><td>Cup</td><td>4 group games; group and knockout games count; the final does not</td><td>Commissioner's Cup final does not count</td></tr>\n<tr><td>Period length; overtime</td><td>720 s; 300 s</td><td>600 s; 300 s</td></tr>\n</tbody></table>\n<p>Every season from 1997 on has a format, so history pages and the backtest run, but only the current format needs to be exact:</p>\n<ul>\n<li>NBA:\n<ul>\n<li>29 teams to 2004;</li>\n<li>50 games in 1999, 66 in 2012, and 72 in 2020 and 2021 (the 2020 bubble, with its 8-v-9 play-in, is noted rather than modelled);</li>\n<li>the play-in from 2021;</li>\n<li>a best-of-5 first round to 2002;</li>\n<li>2-3-2 Finals from 1985 to 2013;</li>\n<li>two divisions per conference to 2004;</li>\n<li>the 1995 lottery table with 3 picks drawn before 2019;</li>\n<li>the Cup from 2024.</li>\n</ul></li>\n<li>WNBA:\n<ul>\n<li>best-of 3, 5, 5 from 2022 to 2024;</li>\n<li>single-game first two rounds then best-of-5 from 2016 to 2021 (simplified as a bracket without the byes);</li>\n<li>before 2016, four playoff teams per conference with best-of 3, 3, 5.</li>\n</ul></li>\n</ul>\n<p>The NBA 2026 and WNBA 2026 formats were checked against ESPN standings. The tiebreak order, play-in shape, 2-2-1-1-1 pattern, lottery table and Cup rules were taken from the published rules. Historical WNBA team and game counts are marked unverified.</p>\n<span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n\n<h3>Postseason</h3>\n<p>NBA play-in: 7 hosts 8, and the winner is the 7th seed. 9 hosts 10, and the loser is out. The loser of 7-v-8 then hosts the winner of 9-v-10 for the 8th seed.</p>\n<p>The bracket is fixed with no reseeding, in the order 1-8, 4-5, 3-6, 2-7, and the higher seed holds home court in every series. In a two-conference league the Finals pair the conference champions, and the better regular-season record holds home court. Each game uses the end-of-season strengths x_end = rating + z + the walk's final value:</p>\n<div class=\"eq\">P(A wins a game at home) = Phi( ((x_A - x_B) * P / 100 + HCA) / sigma_n )\nP(A wins a game away)    = Phi( ((x_A - x_B) * P / 100 - HCA) / sigma_n )</div>\n<p>Playoff games do not use rest or travel terms.</p>\n<p>Once the regular season is over, the seeds are computed once and fixed. They can be overridden, and observed first-round pairings override the computed bracket slots. The higher computed seed of each observed pair keeps home court.</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span>\n\n<h3>Draft lottery (NBA)</h3>\n<p>The 14 teams that miss the playoffs take the lottery slots in reverse order of win percentage, with ties broken at random. Play-in losers are among them. Picks 1 to 4 (1 to 3 before 2019) are drawn without replacement, in proportion to each slot's combinations out of 1,000, and the remaining picks follow slot order. The slot-to-pick probabilities are enumerated exactly once. Pick trades and protections are not modelled: each team is shown its own pick.</p>\n<table class=\"tbl\"><thead><tr><th>Table</th><th>Combinations by slot 1 to 14</th></tr></thead><tbody>\n<tr><td><code>LOTTERY_2019</code> (from 2019, 4 draws)</td><td>140, 140, 140, 125, 105, 90, 75, 60, 45, 30, 20, 15, 10, 5</td></tr>\n<tr><td><code>LOTTERY_1995</code> (before 2019, 3 draws)</td><td>250, 199, 156, 119, 88, 63, 43, 28, 17, 11, 8, 7, 6, 5</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n\n<h3>Outputs</h3>\n<p>For each team the simulation gives:</p>\n<ul>\n<li>expected wins and losses, the 5th and 95th percentiles of final wins, and the full distribution P(W = k);</li>\n<li>the seed distribution;</li>\n<li>P(playoffs), which includes play-in winners, and P(play-in), which is finishing 7th to 10th;</li>\n<li>P(top 6) and, in the NBA, P(division);</li>\n<li>P(reaching each round);</li>\n<li>P(conference), which is reaching the Finals (in the WNBA, being a finalist), and P(title);</li>\n<li>in the NBA, the distribution of its lottery pick.</li>\n</ul>\n<p>For each team's next game, the same probabilities are also given conditional on winning it and on losing it. The bracket lists the 24 most frequent match-ups in each round, with the share won by the team holding home court.</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span>\n\n<h3>Magic and tragic numbers</h3>\n<p>These are exact counts from the current table, not simulated. For the target \"finish in the top k of group X\":</p>\n<div class=\"eq\">M_ij = W_j + R_j - W_i + 1      (wins by i plus losses by j that put j out of reach; +1 assumes i loses the tiebreak)\nmagic_i  = k-th largest M_ij over rivals j in the group;    clinched when &lt;= 0\ntragic_i = k-th smallest (W_i + R_i - W_j + 1);             eliminated when &lt;= 0</div>\n<p>W is wins so far and R games remaining. The NBA targets are top 6, postseason (top 10, the play-in places), division and top seed. The WNBA targets are postseason (top 8) and top seed.</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span>\n</section>\n\n<section id=\"m-elo\">\n<h2>Elo</h2>\n<p>Game Elo follows FiveThirtyEight's NBA recipe. It runs over every season on disk, from 1997, as a baseline for the backtest and for history pages. Regular-season, Cup, play-in and playoff games are rated; pre-season and All-Star games are not.</p>\n<div class=\"eq\">E_home = 1 / (1 + 10^( -(R_h - R_a + HCA * [not neutral]) / 400 ))\nR_h &lt;- R_h + K * M * (S_home - E_home),     R_a &lt;- R_a - (the same)\nM = (|MOV| + 3)^0.8 / (7.5 + 0.006 * D),    D = winner's Elo minus loser's, home court included\nbetween seasons:  R &lt;- carry * R + (1 - carry) * mean\npoint-spread equivalent:  spread_home = -(R_h - R_a + HCA) * pts_per_elo</div>\n<p>The margin-of-victory multiplier M grows with the margin, but grows less when the favourite wins, which damps the autocorrelation a plain MOV multiplier would cause. A team's first game is rated at the mean if it appears in the first season on disk, and at <code>new_team</code> if it appears later, which in practice means an expansion team. Forecasts use each team's last post-game rating strictly before the game's day, without the between-season regression.</p>\n<table class=\"tbl\"><thead><tr><th><code>ELO_DEFAULTS</code> key</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>k</code></td><td>20</td><td>20</td></tr>\n<tr><td><code>hca</code> (Elo points)</td><td>100</td><td>90</td></tr>\n<tr><td><code>carry</code> (share kept between seasons)</td><td>0.75</td><td>0.70</td></tr>\n<tr><td><code>mean</code></td><td>1505</td><td>1505</td></tr>\n<tr><td><code>new_team</code></td><td>1300</td><td>1350</td></tr>\n<tr><td><code>pts_per_elo</code></td><td>1/28</td><td>1/30</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/elo.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span>\n</section>\n\n<section id=\"m-shots\">\n<h2>Shot quality (xPTS)</h2>\n<p>The shot model gives the probability that a field-goal attempt goes in, from where and how it was taken, and the expected points that implies. It is fitted separately for each league and season, on that season's shot table.</p>\n<h3>Model</h3>\n<div class=\"eq\">logit P(make) = a\n              + f_dist(dist_ft)              piecewise-linear spline on DIST_KNOTS\n              + f_angle(|angle_deg|)         piecewise-linear spline on ANGLE_KNOTS\n              + zone + shot_type             one-hot\n              + b_3 * [three] + b_ast * assisted + b_pb * putback + b_tr * transition\n              + period (1, 2, 3, 4, OT)\n              + clock (end: &lt;= 4 s left in the period; late: &lt;= 24 s; else normal)\n              + margin before the shot (&lt;= -10, -9..-4, -3..3, 4..9, &gt;= 10)\n              + league (only when a table mixes leagues)\nxPTS = P(make) * value (2 or 3)</div>\n<p>The smooth terms carry a second-difference (P-spline) penalty, plus a tiny ridge. The one-hot and indicator terms carry a ridge, equivalent to a N(0, 1) prior on each log-odds, and the intercept is free. The model is fitted by Newton's method (iteratively reweighted least squares) with step halving on a sparse design.</p>\n<p>A block is not a feature, because it is an outcome: a blocked shot is always a miss. Free throws are outside the shot table, so the extra point of an and-one is not in xPTS. The zone and intercept terms are close to unpenalised, so the fit is calibrated by zone within the season it is fitted on. This makes xPTS a measure of shot difficulty relative to that season's league, not an out-of-sample forecast.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td><code>DIST_KNOTS</code> (ft)</td><td>0, 1, 2, 3, 4, 5, 6, 8, 10, 12, 14, 16, 18, 20, 22, 23, 24, 25, 26, 28, 30, 34, 40, 50, 94</td></tr>\n<tr><td><code>ANGLE_KNOTS</code> (degrees)</td><td>0, 15, 30, 45, 60, 75, 90, 120, 180</td></tr>\n<tr><td><code>LAMBDA_SMOOTH</code></td><td>30 (second-difference penalty on both splines)</td></tr>\n<tr><td><code>LAMBDA_TINY</code></td><td>0.001 (ridge on the spline coefficients)</td></tr>\n<tr><td><code>LAMBDA_CAT</code></td><td>1.0 (ridge on one-hot and indicator terms: prior sd 1)</td></tr>\n<tr><td>Minimum shots to fit</td><td>50</td></tr>\n<tr><td><code>MODEL_VERSION</code></td><td>xpts-1</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/shots.py</span><span class=\"src\">oddsmarkets/basketball/models/_io.py</span>\n\n<h3>Shot-making and derived tables</h3>\n<div class=\"eq\">pox    = points - xPTS                         (points over expected)\npox100 = 100 * pox / shots\nse(pox100) = 100 * sqrt( sum value^2 * p * (1 - p) ) / shots\npox100_shrunk = 100 * pox / (shots + 250)      (SHRINK_SHOTS pseudo-shots at zero)</div>\n<ul>\n<li>Per shooter and per team: shots, makes, points, xPTS, FG%, points per shot, xPTS per shot and pox100, with its standard error and its shrunk version.</li>\n<li>Per defending team: the xPTS per shot its opponents took (the shot quality it conceded) and their pox100. A positive pox100 means opponents made more than expected, which is a mix of luck and contests the data cannot see.</li>\n<li>Shot diet: the share and FG% by zone and by shot type, against the league.</li>\n<li>Shot profile: the frequency of rim, paint, mid-range, three and corner-three attempts, average distance, the assisted share of makes, the putback and transition frequencies, xPTS per shot and pox100. The box-impact model uses the rim frequency, three frequency and shrunk pox100.</li>\n<li>League grid: hexagons of 1.5 ft circumradius (or squares) over x -25 to 25 and y 0 to <code>GRID_Y_MAX</code> = 35 ft, with the make rate, points per shot and xPTS per shot in each cell. Player and team charts are drawn against it.</li>\n<li>Distance curve: the make probability by distance for a straight-on, unassisted half-court jumper in the second period, with a normal clock and a tied score.</li>\n</ul>\n<span class=\"src\">oddsmarkets/basketball/models/shots.py</span>\n\n<h3>Calibration</h3>\n<p>Observed against predicted, by zone, by shot type and by decile of predicted probability. Each table gives n, FG%, mean predicted probability, points, xPTS, Brier score, and:</p>\n<div class=\"eq\">z = (FG% - mean p) * n / sqrt( sum p * (1 - p) )</div>\n<p>See <a href=\"#/calibration\">Calibration</a>.</p>\n<span class=\"src\">oddsmarkets/basketball/models/shots.py</span>\n</section>\n\n<section id=\"m-impact\">\n<h2>Player impact</h2>\n<p>Player impact is built in four layers:</p>\n<ul>\n<li>RAPM, which measures a player from the scoring margins of the player's lineups;</li>\n<li>box impact, which predicts RAPM from box-score rates;</li>\n<li>Hardwood Plus-Minus (HPM), a precision-weighted combination of the two;</li>\n<li>projections, which carry a player's rates and HPM forward.</li>\n</ul>\n<p>All four are in points per 100 possessions. Offence (O) and defence (D) are kept separately, the total is T = O + D, and a positive D is good defence.</p>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n\n<h3>RAPM</h3>\n<p>Each lineup stint gives two observations, one for each offence:</p>\n<div class=\"eq\">y = 100 * pts_off / poss_off - league ORtg\n  = sum_(i on offence) O_i - sum_(j on defence) D_j + hca * s + e\ns = +0.5 (home offence), -0.5 (away offence);   weight = poss_off;   Var(e) = sigma^2 / poss_off\nprior: O_i, D_i ~ N(m_i, sigma^2 / lambda),   hca ~ N(0, sigma^2 / 0.001)\nsolve: (X'WX + Lambda) b = X'Wy + Lambda m        (sparse X, dense Cholesky)\ncov(b) = sigma^2 (X'WX + Lambda)^-1,   sigma^2 = weighted RSS / (n - trace((X'WX + Lambda)^-1 X'WX))</div>\n<p>The league ORtg here is the points per 100 possessions over all of the season's stints. The ridge strength lambda is chosen from a grid by 5-fold cross-validation, with whole games held out, scored by the weighted squared error per possession.</p>\n<p>The prior centre m is zero in the first season on disk. In later seasons it is the player's previous-season estimate times <code>PRIOR_CARRY</code>. Seasons are fitted in sequence, each centred on the one before, up to 12 seasons back. A player with few possessions stays near the prior: that is the shrinkage.</p>\n<p>The standard errors of O, D and T come from the posterior covariance, and the standard error of T includes the covariance between O and D. Possessions are counted at both ends.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td><code>RIDGE_GRID</code> (lambda, in possessions)</td><td>250, 500, 1000, 2000, 3500, 6000, 10000</td></tr>\n<tr><td><code>DEFAULT_RIDGE</code></td><td>2000</td></tr>\n<tr><td><code>CV_FOLDS</code></td><td>5 (folds of whole games)</td></tr>\n<tr><td><code>HCA_RIDGE</code></td><td>0.001</td></tr>\n<tr><td><code>PRIOR_CARRY</code></td><td>0.8</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n\n<h3>Box rates</h3>\n<p>Per player and season, from regular-season box scores:</p>\n<div class=\"eq\">on_poss = team_poss * sec / (team player-seconds / 5)          possessions on the floor\nrate100(stat) = 100 * stat / on_poss                              pts, fga, tpa, fta, ast, tov, oreb, dreb, stl, blk, pf\nTSA = FGA + 0.44 * FTA,   TS% = PTS / (2 * TSA)\nts_add = (TS_shrunk - lg_TS) * 2 * 100 * TSA / on_poss,   TS_shrunk = (PTS + 2 * 50 * lg_TS) / (2 * (TSA + 50))\n3PA rate = (3PA + 20 * lg_3PAr) / (FGA + 20),   FT rate = (FTA + 20 * lg_FTr) / (FGA + 20)\nusage = 100 * (FGA + 0.44 * FTA + TOV) / on_poss</div>\n<p>A player's team is the one the player played most minutes for. Team offensive and defensive ratings come from the box scores, and each player's five-man share of the team's minutes is also recorded.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td><code>TS_PSEUDO</code></td><td>50 true-shooting attempts at league average added before ts_add</td></tr>\n<tr><td><code>RATE_PSEUDO_FGA</code></td><td>20 pseudo-FGA at the league rate for 3PA rate and FT rate</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n\n<h3>Box impact</h3>\n<p>This is the site's equivalent of BPM: a possession-weighted ridge regression of RAPM O and of RAPM D on standardised box features. It is pooled over every season on disk that has stints, which means every play-by-play season.</p>\n<ul>\n<li>Box features (<code>BOX_FEATURES</code>): pts100, ts_add, 3PA rate, FT rate, ast100, tov100, oreb100, dreb100, stl100, blk100, pf100, usage, and indicators for the G and F pools.</li>\n<li>Shot features (<code>SHOT_FEATURES</code>, play-by-play seasons only): rim frequency, three frequency and shrunk pox100.</li>\n</ul>\n<p>Two variants are fitted: \"full\" uses both sets, and \"box\" uses the box features alone. A player whose shot features are present gets the full variant; box-only seasons get the box variant.</p>\n<div class=\"eq\">weight = min(possessions, 4000)                     (BOX_WEIGHT_CAP)\nridge  = 5.0 * sum(weight) / 1000 on standardised features, free intercept   (BOX_RIDGE)</div>\n<p>As in BPM, a team adjustment then adds one constant per team. It makes the minutes-weighted five-man sum of box O equal the team's offensive rating minus the league's, and the sum of box D equal the league's rating minus the team's defensive rating. The team ratings use only games with a box score, and the adjustment is skipped for a team with fewer than 10 such games (<code>MIN_TEAM_BOX_GAMES</code>). Before this rule, Chicago's 2015-16 season, which has a box score in only one game, put offence and defence splits of about plus and minus 48 on its players. The residual variance tau^2 is the possession-weighted variance of (RAPM - box) minus the mean squared RAPM standard error, floored at <code>TAU2_FLOOR</code> = 0.25. It is the prior variance HPM uses. Each variant also reports its in-sample R^2.</p>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n\n<h3>Hardwood Plus-Minus (HPM)</h3>\n<div class=\"eq\">HPM_side = (box / tau^2 + RAPM / se^2) / (1 / tau^2 + 1 / se^2)       side = O, D\nse_HPM_side = (1 / tau^2 + 1 / se^2)^(-1/2)\nHPM = HPM_O + HPM_D,   se_HPM = sqrt(se_O^2 + se_D^2)</div>\n<p>HPM always lies between its two inputs, and leans further towards RAPM as possessions accumulate. A player with no RAPM, as in box-only seasons, gets the box impact with standard error tau; tau^2 defaults to 4 if a variant has none. RAPM is already shrunk towards its own prior, so this is the simple combination of two noisy measurements, not a joint posterior. The page shows the weight placed on RAPM for each side.</p>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n\n<h3>Projections</h3>\n<p>Projections are built for each player from the player's games in the current and previous seasons, using games strictly before the projection date.</p>\n<div class=\"eq\">rate36(stat) = 36 * ( sum_g w_g * stat_g + 250 * pool_rate(stat) ) / ( sum_g w_g * min_g + 250 )\nw_g = 0.5 ^ (k / 60),   k = games ago (0 = most recent)\nexpected minutes = sum_g v_g * min_g / sum_g v_g,   v_g = 0.5 ^ (k / 12)\navailability = share of the current team's last 20 games played\nHPM_next = HPM + aging(age)</div>\n<p>pool_rate is the per-minute rate of the player's position pool. The aging adjustment is the expected change in HPM over the next season, interpolated linearly between knots. The knots were set by hand from the published aging literature, not fitted here.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td><code>HALF_LIFE_GAMES</code></td><td>60 games</td></tr>\n<tr><td><code>MINUTES_HALF_LIFE</code></td><td>12 games</td></tr>\n<tr><td><code>PRIOR_MINUTES</code></td><td>250 pseudo-minutes at the pool rate</td></tr>\n<tr><td><code>AGE_CURVE</code> (age: change in HPM per season)</td><td>19: +1.2, 21: +0.9, 23: +0.6, 25: +0.3, 27: 0.0, 29: -0.25, 31: -0.6, 33: -1.0, 35: -1.4, 38: -2.0</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n\n<h3>Roster impact</h3>\n<div class=\"eq\">net = sum_p HPM_p * m_p / G + REPLACEMENT_HPM * fill / G\nG = 48 (NBA) or 40 (WNBA) minutes,   fill = max(0, 5G - sum m_p)\n(minutes above 5G are scaled down to 5G)</div>\n<p>This is the five-man HPM sum per 100 possessions over a roster's expected minutes. Any unfilled minutes are played at <code>REPLACEMENT_HPM</code> = -2.0, which matches the game model's replacement level. The difference between a full roster and one depleted by injuries is the injury effect, and the roster sum is the input the preseason prior can blend in.</p>\n<span class=\"src\">oddsmarkets/basketball/models/impact.py</span>\n</section>\n\n<section id=\"m-winprob\">\n<h2>Win probability and WPA</h2>\n<h3>Model</h3>\n<p>The state after each play is:</p>\n<ul>\n<li>the margin m (home minus away);</li>\n<li>the seconds left tau: the regulation time left, or the time left in the current overtime;</li>\n<li>possession p: +1 home, -1 away, 0 unknown;</li>\n<li>the pregame expected home margin s;</li>\n<li>the league.</li>\n</ul>\n<p>If the rest of the game were a random walk with drift s / T per second, the home side would win with probability Phi((m + s*u + c*p) / (sigma * sqrt(tau))), where T is the regulation length (2,880 s NBA, 2,400 s WNBA) and u = tau / T. The model fits the logistic analogue of this with time-varying coefficients:</p>\n<div class=\"eq\">logit P(home wins) = [ b1 m + b2 m u + b3 s u + b4 p + b5 p u ] / sqrt(tau + K)\ns = -spread_home (DraftKings via ESPN pickcenter); with no line, s = DEFAULT_HCA at a home venue, 0 at a neutral one</div>\n<p>The model has no intercept, so a pick'em game (s = 0) at tip-off is exactly 0.5, and home court enters only through s. K regularises the end of the game and is chosen from a grid by log-likelihood. The coefficients are fitted by Newton's method with a small ridge.</p>\n<p>A finished game (no time left, regulation complete, margin not zero) is 1 or 0 exactly. A tie with no time left goes to overtime. Fouls to give, the bonus and timeouts are not in the model, because the compact play-by-play carries no team-foul counts.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>NBA</th><th>WNBA</th></tr></thead><tbody>\n<tr><td><code>K_GRID</code> (s)</td><td colspan=\"2\">2, 5, 10, 20, 40, 80</td></tr>\n<tr><td><code>RIDGE</code></td><td colspan=\"2\">0.001</td></tr>\n<tr><td><code>DEFAULT_HCA</code> (points, only when there is no line)</td><td>2.5</td><td>2.0</td></tr>\n<tr><td>Regulation T (s)</td><td>2880</td><td>2400</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/winprob.py</span>\n\n<h3>Training</h3>\n<p>For a season, the model is fitted on every play-by-play state of up to three earlier seasons on disk, labelled with each game's result. The season itself is then out of sample. Only when no earlier play-by-play exists does the fit include the season itself. Possession comes from the parsed possessions, matched by event index. Failing that, it is matched by time, and failing that it is inferred from the play text: a made field goal or a made last free throw hands the ball over, a defensive rebound or steal changes it, an offensive rebound keeps it, and the last known possession carries on, resetting at each period.</p>\n<span class=\"src\">oddsmarkets/basketball/models/winprob.py</span>\n\n<h3>WPA</h3>\n<p>For each play, dWP = WP(after) - WP(before). Possession is read after the play, so a made basket, a turnover or a made last free throw already hands the ball over, and a missed shot leaves a loose ball that the shooting side keeps only at the offensive-rebound rate (<code>OREB_FG</code>, <code>OREB_FT</code>). The miss therefore carries most of the lost possession and the defensive rebound only the rest.</p>\n<p>Each play is credited in full to both teams, each in its own terms (+dWP to the home side, -dWP to the away side), as in baseball WPA:</p>\n<ul>\n<li>On the acting team, the listed participants share it: the first actor 1 - <code>ASSIST_SHARE</code> and a listed team-mate (the assister) the rest.</li>\n<li>On the other team, a listed player (blocker, stealer, fouled player) takes <code>DEF_SHARE</code> and the five on the floor split the remainder. With nobody listed, the five on the floor share all of it.</li>\n<li>A team with nobody to credit (no lineup known, or the final step to 1 or 0) books its share to \"unattributed\".</li>\n</ul>\n<p>The accounting is exact for each team, so a team's players add up to its own change in win probability:</p>\n<div class=\"eq\">sum(team's players' WPA) + unattributed(team) = team's WP(final) - WP(tip-off)</div>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td><code>DEF_SHARE</code></td><td>0.5</td></tr>\n<tr><td><code>ASSIST_SHARE</code></td><td>0.3</td></tr>\n<tr><td><code>OREB_FG</code>, <code>OREB_FT</code></td><td>0.27, 0.14</td></tr>\n<tr><td><code>CLUTCH_S</code>, <code>CLUTCH_MARGIN</code></td><td>300 s, 5 points</td></tr>\n</tbody></table>\n<span class=\"src\">oddsmarkets/basketball/models/winprob.py</span>\n\n<h3>Leverage, clutch, excitement and comeback</h3>\n<div class=\"eq\">slope = |WP(m + 1) - WP(m - 1)| / 2                     at the state before the play\nLI = slope / mean(slope over the fitting states)          (1 = an average moment)\nleverage-adjusted WPA = sum over plays of credit / max(LI, 0.1)\nexcitement = sum over the game of |dWP|\ncomeback   = the eventual winner's lowest win probability during the game</div>\n<p>The clutch state is the NBA definition: the fourth period or overtime, with 5 minutes or less left and the margin within 5 points, judged before the play. Clutch WPA sums a player's credit over plays that start in that state.</p>\n<span class=\"src\">oddsmarkets/basketball/models/winprob.py</span>\n\n<h3>Calibration against ESPN</h3>\n<p>ESPN publishes its own per-play home win probability. Both models are scored on the same states with the Brier score, log-loss and a 10-bin reliability table, and the mean absolute difference between them is reported. See <a href=\"#/calibration\">Calibration</a>.</p>\n<span class=\"src\">oddsmarkets/basketball/models/winprob.py</span>\n</section>\n\n<section id=\"m-awards\">\n<h2>Award races</h2>\n<p>The site models six awards: MVP, Rookie of the Year, Defensive Player of the Year, Sixth Man (Sixth Player in the WNBA), Most Improved and Clutch Player of the Year (NBA only).</p>\n<h3>Model</h3>\n<div class=\"eq\">P(i wins | pool) = exp(theta_i) / sum_(j in pool) exp(theta_j),     theta_i = sum_k w_k z_ik</div>\n<p>z_ik is feature k of player i, standardised within that season's candidate pool. Standardising this way makes eras and leagues with different scoring levels comparable. This is a conditional logit, the same as a Plackett-Luce model truncated at the winner.</p>\n<p>The weights w are fitted on past winners by maximising sum over seasons of log P(winner) - 0.5 * <code>RIDGE</code> * |w|^2, using L-BFGS starting from the default weights. A season with co-winners counts each with weight 1/k. The fit needs at least three past seasons whose winner is in the pool; otherwise the hand-set defaults below are used. The past winners are entered in the code, verified on 1 October 2026 against the published award histories, and matched to ESPN ids by name, ignoring accents, case and suffixes.</p>\n<table class=\"tbl\"><thead><tr><th>Award</th><th>Features (<code>FEATURES</code>)</th><th>Default weights (<code>DEFAULT_WEIGHTS</code>)</th><th>Pool beyond the floor</th></tr></thead><tbody>\n<tr><td>MVP</td><td>hpm_value, ppg, team_win_pct, hpm_t</td><td>1.6, 0.8, 1.0, 0.4</td><td>none</td></tr>\n<tr><td>ROY</td><td>ppg, mpg, hpm_value, team_win_pct</td><td>1.6, 0.6, 0.6, 0.2</td><td>rookies</td></tr>\n<tr><td>DPOY</td><td>hpm_d_value, bpg, spg, dpg (defensive rebounds), team_def</td><td>1.2, 0.8, 0.4, 0.4, 0.8</td><td>none</td></tr>\n<tr><td>Sixth Man</td><td>ppg, hpm_value, mpg, team_win_pct</td><td>1.6, 0.6, 0.4, 0.4</td><td>started fewer than half their games</td></tr>\n<tr><td>MIP</td><td>d_hpm, d_ppg, d_mpg, ppg</td><td>1.2, 1.2, 0.6, 0.4</td><td>played the previous season</td></tr>\n<tr><td>Clutch</td><td>clutch_wpa, wpa, team_win_pct</td><td>1.6, 0.4, 0.8</td><td>has clutch play-by-play</td></tr>\n</tbody></table>\n<div class=\"eq\">hpm_value   = (HPM_T + 2.0) * minutes / G / 10      (G = 48 NBA, 40 WNBA)\nhpm_d_value = (HPM_D + 1.0) * minutes / G / 10\nteam_def    = league ORtg - team DRtg\nd_x         = this season's x - last season's x</div>\n<p>Every pool has a floor: a player must have played at least <code>MIN_GAMES_SHARE</code> = 0.4 of the team's games so far and average at least <code>MIN_MPG</code> = 12 minutes. A rookie is a player not seen in any earlier season on disk. While fewer than 5 earlier seasons are on disk, a newcomer counts as a rookie only if aged 24 or younger, so that veterans whose earlier seasons are simply missing are not counted.</p>\n<span class=\"src\">oddsmarkets/basketball/models/awards.py</span><span class=\"src\">oddsmarkets/basketball/models/award_winners.py</span>\n\n<h3>The 65-game rule</h3>\n<p>From the 2024 NBA season (<code>RULE_65_FROM</code>), MVP, DPOY, MIP and Clutch need 65 qualifying games (<code>RULE_65_GAMES</code>). A game qualifies at 20 or more minutes, and at most two games of 15 to 20 minutes also count. ROY and Sixth Man are left out of the rule here, because the code's author was not certain how it applies to them. The rule's exceptions, such as season-ending injuries, are not modelled. The WNBA has no such rule.</p>\n<span class=\"src\">oddsmarkets/basketball/models/awards.py</span>\n\n<h3>Projection to season end</h3>\n<p>Each race is simulated <code>N_SIMS</code> = 5,000 times to the end of the season:</p>\n<ul>\n<li>A player's remaining games ~ Binomial(the team's games left, the player's share of team games so far, clipped to 0.02 to 1). Counting stats accumulate at the player's per-game rates.</li>\n<li>HPM drifts by N(0, 1.5^2 * share of season left) (<code>HPM_DRIFT_SD</code> = 1.5), and defensive HPM by half that draw.</li>\n<li>Team wins are Normal(expected wins, ((95th - 5th percentile) / 3.29)^2) from the season simulation, clipped to what is still possible. Without a simulation they are current wins + Binomial(games left, current win %).</li>\n<li>Qualifying games grow at the player's qualifying rate.</li>\n</ul>\n<p>The features are recomputed and restandardised in every simulation, and ineligible players are removed. The winner is then drawn with the Gumbel-max trick, which gives an exact Plackett-Luce first place. P(win) and P(top 3) are shares of simulations. The race also says whether a player can still reach 65 games, and in what share of simulations that happens.</p>\n<span class=\"src\">oddsmarkets/basketball/models/awards.py</span>\n</section>\n\n<section id=\"m-markets\">\n<h2>Markets</h2>\n<p>Market numbers come from two prediction markets, Kalshi and Polymarket, and from the DraftKings line ESPN carries. All three are mapped to ESPN team and player ids.</p>\n<h3>What is read</h3>\n<table class=\"tbl\"><thead><tr><th>Market</th><th>Kalshi series</th><th>Polymarket (found by event title)</th></tr></thead><tbody>\n<tr><td>Champion</td><td>KXNBA, KXWNBA</td><td>\"NBA: 2027 Champion\", \"WNBA: 2026 Champion\"</td></tr>\n<tr><td>Conference champion (NBA)</td><td>KXNBAEAST, KXNBAWEST</td><td>Eastern / Western Conference Champion</td></tr>\n<tr><td>NBA Cup</td><td>KXNBACUP (labelled by the calendar year of its December final)</td><td>NBA Cup Winner</td></tr>\n<tr><td>MVP, ROY, DPOY</td><td>KXNBAMVP, KXNBAROY, KXNBADPOY; KXWNBAMVP, KXWNBAROY, KXWNBADPOY</td><td>by title</td></tr>\n<tr><td>Sixth Man / Sixth Player, Clutch</td><td>KXNBASIXTH, KXNBACLUTCH; KXWNBA6POY</td><td>by title</td></tr>\n<tr><td>Make playoffs / play-in (NBA, per team yes/no)</td><td>KXNBAPLAYOFF, KXNBAPLAYIN</td><td>Team to Make Playoffs / Play-In</td></tr>\n<tr><td>Win totals (per team ladders of \"N+ wins\")</td><td>KXNBAWINS, KXWNBAWINS</td><td>not used</td></tr>\n<tr><td>Games</td><td>KXNBAGAME, KXWNBAGAME</td><td>nba-&lt;a&gt;-&lt;b&gt;-YYYY-MM-DD moneyline</td></tr>\n</tbody></table>\n<p>Kalshi events are selected by the season's two-digit suffix on the event ticker. Polymarket events must name the season (or \"2026-27\"), or end in that year if their title names no year. Closed Polymarket events are skipped.</p>\n<span class=\"src\">oddsmarkets/basketball/sources/markets.py</span>\n\n<h3>Market numbers and the thin-market rule</h3>\n<p>A market number is the midpoint of a live two-sided quote. A last trade is never used.</p>\n<div class=\"eq\">mid = (bid + ask) / 2   when 0 &lt; bid &lt;= ask &lt; 1 and ask - bid &lt;= 0.12 (MAX_SPREAD); otherwise no number</div>\n<p>For a field market (champion, conference, Cup, awards), the mids from the two sources are averaged for each runner. Each runner is then accounted for in one of three ways:</p>\n<ul>\n<li>it has a number;</li>\n<li>it has no bid and an ask of 2c or less (<code>FLOOR_ASK</code>), and counts as zero;</li>\n<li>it is settled No.</li>\n</ul>\n<p>The market is published only when two conditions hold:</p>\n<ul>\n<li>at least max(4, half the field) runners are accounted for;</li>\n<li>the implied total of the mids lies between 0.8 and 1.3 (<code>MIN_TOTAL</code>, <code>MAX_TOTAL</code>).</li>\n</ul>\n<p>It is then de-vigged multiplicatively:</p>\n<div class=\"eq\">fair_i = mid_i / sum_j mid_j</div>\n<p>The field is every team for team markets (the conference's teams for conference markets). For award markets it is the runners the markets list, not every player in the league. A settled market is shown as settled, without a number. The playoff and play-in markets are per-team yes/no questions, so they are not a field: they show the mean mid across sources, with a settled No counted as zero, and are not de-vigged.</p>\n<span class=\"src\">oddsmarkets/basketball/sources/markets.py</span><span class=\"src\">oddsmarkets/common/prediction_markets.py</span><span class=\"src\">oddsmarkets/common/markets.py</span>\n\n<h3>Win totals</h3>\n<p>Each Kalshi win-total event is a ladder of \"N+ wins\" markets. The ladder is forced to be non-increasing by taking the running minimum from the lowest N up. The line is N - 0.5 at the rung whose number is closest to 0.5, and P(over) is that rung's number. The payload contract pairs it with the model's P(over), read from the season simulation's win distribution.</p>\n<span class=\"src\">oddsmarkets/basketball/sources/markets.py</span>\n\n<h3>Games</h3>\n<p>Market events are matched to the store's games by the pair of teams, within one day of the market's date. The exact date is preferred when two games match.</p>\n<ul>\n<li>Kalshi lists one market per team. With both sides quoted, p_home = mid_home / (mid_home + mid_away), which removes the vig; with one side, its mid (or one minus it) is used.</li>\n<li>Polymarket's moneyline is one market with two outcomes, so p_home is the first outcome's mid, or one minus it.</li>\n<li>The DraftKings moneylines are converted to probabilities (100 / (ml + 100) for an underdog, -ml / (-ml + 100) for a favourite) and de-vigged across the two sides. The DraftKings spread is converted through the game model's spread conversion.</li>\n</ul>\n<p>The market p_home is the mean of the prediction-market sources. Without them it is the DraftKings moneyline, and failing that the DraftKings spread. The basis used is recorded with the number.</p>\n<span class=\"src\">oddsmarkets/basketball/sources/markets.py</span><span class=\"src\">oddsmarkets/basketball/models/game.py</span>\n\n<h3>Matching names</h3>\n<ul>\n<li>Teams: a Kalshi ticker's team code is mapped through an alias table to ESPN abbreviations (for example GSW to GS, NYK to NY, UTA to UTAH; CONN to CON in the WNBA). Failing that, labels such as \"Los Angeles C\" are matched by location plus the nickname's initial. Then exact location-and-name, nickname or location matches are tried, then a label that ends with a unique nickname, and finally fuzzy matching.</li>\n<li>Players: an exact match on the folded name is tried first, then fuzzy matching with a floor of 0.85, then a unique family name.</li>\n<li>Fuzzy matching scores 0.93 when one name's tokens are a subset of the other's, and otherwise uses difflib's ratio. It refuses a match when the runner-up is within 0.02 or the best score is below the floor (0.72 by default).</li>\n</ul>\n<p>Unmatched labels are reported, not guessed.</p>\n<span class=\"src\">oddsmarkets/basketball/sources/markets.py</span><span class=\"src\">oddsmarkets/common/prediction_markets.py</span>\n\n<h3>Differences from the market</h3>\n<p>The markets payload pairs the model's home-win probability with the market's for the next three days' games (the difference is the model minus the market), and the futures and win-total tables show model and market side by side. Differences on preseason win totals are not shown.</p>\n<p>How good are these models against the betting market? A study against the market (2 October 2026; the repository's <code>docs/research/basketball_edge.md</code>) tested them walk-forward on 2024-2026, the seasons for which ESPN has opening and closing lines. The site's game model on its own does not beat the market: the closing line is better than any of our forecasts, and bets on the model's disagreements with the opening line lose to the vig. A research model that also uses ratings implied by past closing lines did gain on opening lines: in the WNBA on all three markets (closing-line value about +4% a bet), in the NBA only on moneylines (about +3%, mostly at one book in 2024-25), never in the playoffs, and not against Kalshi's game markets at fixed times before tip-off. That advantage exists only for someone who gets the opening line, and it is not shown on this site.</p>\n<span class=\"src\">oddsmarkets/basketball/analytics/season.py</span><span class=\"src\">oddsmarkets/basketball/research/experiments.py</span>\n</section>\n\n<section id=\"m-backtest\">\n<h2>Backtest and calibration</h2>\n<h3>Games</h3>\n<p>The game model is scored on every finished regular-season, Cup, play-in and playoff game of the chosen seasons, using only information available before each game:</p>\n<ul>\n<li>The ratings are refitted weekly from games strictly before the week, with the preseason prior from the previous season.</li>\n<li>The coefficients and sigma are fitted on earlier seasons only; the first season uses the defaults.</li>\n<li>The carry-over slope is fitted on the stores at hand, using teams with 10 or more games in both seasons and needing 40 pairs.</li>\n</ul>\n<p>Five forecasts are compared:</p>\n<ul>\n<li><code>model</code>: the full game model. In the NBA this is the market-informed model wherever it applies, with daily ratings and the fit from earlier seasons only. The local line history fills the games whose store has no line (2024, 2025 and early 2026). For 2017-2026 its log-loss is 0.6127, against 0.6235 for the base model (kept in the file as <code>model_base</code>), and 0.6183 against the DraftKings line's 0.6061 on the games with a line.</li>\n<li><code>model_ratings_only</code>: the same ratings with home court only, without rest, travel, time zones or altitude.</li>\n<li><code>elo</code>: the pregame Elo probability.</li>\n<li><code>market</code>: the DraftKings spread from ESPN pickcenter, converted by p = Phi(-spread_home / sigma_market), with sigma_market fitted on earlier seasons. Only games with a line are scored. This is the line ESPN carried when the finished game was fetched, which is treated as the closing line.</li>\n<li><code>espn</code>: ESPN's pregame predictor, where a game record carries one.</li>\n</ul>\n<div class=\"eq\">log-loss = -mean( y ln p + (1 - y) ln(1 - p) ),   p clipped to [0.0001, 0.9999]\nBrier    = mean( (p - y)^2 )\nreliability: 10 equal-width bins of p, mean p against observed frequency\nmargin RMSE: model mu;  Elo (R_h - R_a + HCA) * pts_per_elo;  market -spread_home</div>\n<p>Every forecast is also scored on the subset of games that have a market line, so the model and the market are compared on identical games. The scores are reported overall and by season, together with the coefficients used in each season.</p>\n<span class=\"src\">oddsmarkets/basketball/models/backtest.py</span>\n\n<h3>Season simulation</h3>\n<p>Each completed season is simulated with 2,000 simulations at four checkpoints: opening day, and 25%, 50% and 75% of the way through the regular season by date. Ratings are fitted through each checkpoint. The forecasts are scored against what happened:</p>\n<ul>\n<li>playoffs: the team appeared in a playoff game;</li>\n<li>finals: P(conference) against appearing in the last playoff game;</li>\n<li>title: the team won the last playoff game.</li>\n</ul>\n<p>A season is skipped if its postseason is not finished or it has fewer than 50 regular-season games.</p>\n<span class=\"src\">oddsmarkets/basketball/models/backtest.py</span>\n\n<h3>Other calibration</h3>\n<p>The shot model is checked by zone, shot type and probability decile, and the win-probability model state by state against outcomes and against ESPN's own win probability. Both are described in their sections. The <a href=\"#/calibration\">Calibration</a> page publishes the backtest. When the build machine has no backtest cache, the committed copy is kept.</p>\n<span class=\"src\">oddsmarkets/basketball/models/shots.py</span><span class=\"src\">oddsmarkets/basketball/models/winprob.py</span><span class=\"src\">oddsmarkets/basketball/PAYLOADS.md</span>\n</section>\n\n<section id=\"m-catalogue\">\n<h2>Percentiles and the player and team catalogues</h2>\n<p>The catalogue builder (<code>scripts/build_hardwood.py</code> with <code>oddsmarkets/basketball/analytics/</code>) is not in the repository at the time of writing. This section describes the contract the pages are built against, as set out in <code>PAYLOADS.md</code>, and will be extended when the builder lands.</p>\n<h3>Metrics</h3>\n<p>Each metric is described by:</p>\n<ul>\n<li>a key and a label;</li>\n<li>a group (for example scoring, shot diet, playmaking, rebounding, defence, impact);</li>\n<li>a format: integer, 1, 2 or 3 decimals, percentage, plus-minus or seconds;</li>\n<li><code>lower</code>, true when a lower value is better, such as turnover rate or points allowed;</li>\n<li><code>scope</code>: \"all\" when it can be computed from box scores in every season from 1997, \"pbp\" when it needs play-by-play and so is null before about 2017;</li>\n<li>a description, which also appears in the <a href=\"#/glossary\">Glossary</a>.</li>\n</ul>\n<p>The contract plans about 120 player metrics and about 70 team metrics.</p>\n<span class=\"src\">oddsmarkets/basketball/PAYLOADS.md</span>\n<h3>Players</h3>\n<p>The season catalogue holds one row per player with at least one game: team, position, pool, age, games, minutes, and whether the player is qualified, which means playing at least the published minutes floor. Each row has every metric value, a percentile against the whole league, a percentile within the player's pool, and a rank. The pools are G, F and C, from ESPN's position (see Identity).</p>\n<p>The plan is to reuse the convention of the sister football site:</p>\n<ul>\n<li>percentiles are computed only among qualified players, using the mid-rank for ties: (below + ties / 2) / n;</li>\n<li>a lower-is-better metric is flipped (100 - percentile), so that 100 is always best;</li>\n<li>a metric with fewer than three values in a pool gets no percentile.</li>\n</ul>\n<p>Until the builder exists, that convention is a plan, not a description of published numbers.</p>\n<span class=\"src\">oddsmarkets/basketball/PAYLOADS.md</span><span class=\"src\">oddsmarkets/football/analytics/players.py</span>\n<h3>Teams and the lab</h3>\n<p>The team catalogue carries the same value, percentile and rank structure, and adds per team:</p>\n<ul>\n<li>the game log;</li>\n<li>the roster with HPM;</li>\n<li>lineups with possessions, offensive, defensive and net ratings, and a shrunk net rating;</li>\n<li>the rotation matrix;</li>\n<li>on/off splits;</li>\n<li>the shot profile for and against, by zone and against the league's points per shot.</li>\n</ul>\n<p>The lab table is column-oriented over every season with box data. Its \"pbp\" metrics are null before about 2017.</p>\n<span class=\"src\">oddsmarkets/basketball/PAYLOADS.md</span>\n</section>\n\n<section id=\"m-value\">\n<h2>Player value, strengths and needs, and the trade simulator</h2>\n<p>The Value page, each team page's \"Strengths and needs\" and the Trade page share one currency and one depth chart. Everything is computed by the build from the models above; the pages only interpolate.</p>\n<h3>Wins above replacement</h3>\n<p>A player's value is the player's HPM measured from a replacement player over the possessions the player was on the floor: PAR (points above replacement) = (HPM + 2.0) &times; possessions / 100, with possessions = minutes &times; league pace / 48 (40 in the WNBA). The replacement level, &minus;2.0 per 100, is the one the injury adjustment and the roster prior already use. WAR = PAR / points per win, and points per win = &sigma; &times; &radic;(2&pi;), &sigma; the game model's fitted margin spread (12.41 NBA, 12.02 WNBA: 31.1 and 30.1 points), because one point of expected margin moves an even game's win probability by &phi;(0)/&sigma;. The rate is HPM itself (per 100 possessions); PAR per game is shown beside it. Percentiles place WAR among the season's qualified players (the catalogue's minutes floor, 20 % of the season's most minutes); players below the floor are placed against them but are never in the \"best at each position\" lists. The trend column is the change in HPM from last season.</p>\n<span class=\"src\">oddsmarkets/basketball/analytics/value.py</span>\n<h3>Guards, wings and bigs</h3>\n<p>ESPN lists only G, F and C, so point guards cannot be told from shooting guards or small from power forwards. Guards are G; bigs are C plus the forwards (150+ minutes) whose box profile is closer to the centres' than the guards': score = z(rebounds per 100) + z(blocks per 100) + z(rim attempt share) &minus; z(three-point attempt rate) &minus; z(assists per 100), z over the season's qualified players, and a forward is a big when the score is above the midpoint of the guards' and centres' mean scores. The other forwards are wings.</p>\n<h3>Rest-of-season value</h3>\n<p>For the current season each rostered player (ESPN's team rosters, plus anyone who played in the last 30 days and is on none) gets rate = (HPM this season &times; minutes + prior &times; 1,000) / (minutes + 1,000), where the prior is last season's HPM plus the aging step (the roster prior's value; the season before for a player who missed last season), offence and defence likewise; a player with no earlier season is pulled towards replacement level with 250 minutes instead of 1,000; minutes per game are the projection's recency-weighted minutes. Next season's rate adds the aging curve's step at the player's age.</p>\n<h3>The depth chart</h3>\n<p>A team's rotation hands each player's projected minutes (capped at 80 % of a game: 38.4 NBA, 32 WNBA) out most first until five players' worth (240 / 200) is used; any shortfall is played at replacement. Team value = &Sigma; rate &times; minutes / 48 + replacement &times; unfilled minutes / 48, in net points per 100. In a trade the outgoing players' minutes open up at their position; each incoming player takes the projected minutes first from open minutes at that position, then from the new team's lowest-rated minutes there (replacement minutes count when they are lower), then at the neighbouring positions, and never from a better player; open minutes left over go to the best remaining players at that position, each at most a quarter of a game more (12 minutes, 10 in the WNBA) and up to the cap (\"next man up\"), then the neighbours, then replacement. The change in team value is the change in the team's net rating for the rest of the season.</p>\n<h3>Grades, strengths and needs</h3>\n<p>Each team's guards, wings and bigs, and its offence, defence, starting five and bench, are valued as projected WAR over a full season from that rotation and placed against the league: A for the top 20 %, then B, C, D and F for the bottom 20 %. The three highest percentiles are the strengths and the three lowest (not already strengths) the weaknesses, each with its value, rank and the player behind it. For each weakness the trade targets are the players on other teams who would add the most there, each added to the team's depth chart with nobody going back (for offence and defence, ranked by that half of HPM); wins and odds come from the sensitivity curves below. Hints come only from the data: the seller's playoff odds (below 15 %: out of contention), what losing the player costs the seller (depth), whether the player is one of the seller's two most valuable players, age and the aging step, and the injury report. \"Attainable\" marks a seller out of contention or with depth, and not a franchise player. Free agents are not identified (ESPN's rosters list signed players only), and there are no salaries: no free, legitimate source is used, so the cap is not checked.</p>\n<h3>Sensitivity curves</h3>\n<p>For every team the build re-runs the whole season simulation (2,000 runs a point, the same random numbers each time) with that team alone shifted by &minus;6, &minus;3, &minus;1.5, 0, +1.5, +3 and +6 net points per 100 for the rest of the season: the shift is added to the team's season-level rating draw, so it moves every remaining game's margin by shift &times; pace / 100 and its playoff strength by the shift. The curves (expected wins, playoffs, top six, Finals, title and, in the NBA, a top-four pick) are made monotone outward from zero. The trade page reads each team's curve at its rating change (linearly between points, the end value beyond &plusmn;6) and adds the difference from the zero point to the full simulation's odds. Each team's curve holds every other team at its rating, so the effect of the two trading teams meeting each other is left out. Without a simulation (the offseason) the page gives wins over a full season from the conversion above and no odds. The curves are cached on the simulation's inputs, so they are recomputed only when a result or a rating changes.</p>\n<span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span><span class=\"src\">docs/hardwood/assets/js/trade.js</span>\n</section>\n<section id=\"m-moves\">\n<h2>Valuation over four seasons, trade ratings and fantasy</h2>\n<p>Added 16 October 2026. Three layers built on the player value above (HPM wins above replacement), for each league's current season. Everything is on-field value from our models: no salaries, contracts or cap, because there is no free source whose terms allow reuse (Spotrac, HoopsHype and Basketball-Reference are left out for that reason), and no fantasy platform's rankings, ownership or ADP (same reason).</p>\n\n<h3>Ages</h3>\n<p>Only the current season's store had dates of birth (they come from today's rosters), so the roster prior's ageing step and every earlier season had no age. <code>scripts/bb_bio.py</code> now reads ESPN's core athlete records (date of birth, draft year, round and pick; paced at 0.6 s, saved every 100 players, resumable) and ESPN's draft lists (every pick, including those who never played) into <code>data/&lt;league&gt;/bio.json</code>: 14,402 of 14,402 NBA player-seasons and 3,565 of 3,678 WNBA player-seasons now have an age. The roster prior uses them through <code>impact.projections</code> (the hand-set ageing step). Checked on past seasons (preseason rosters, the production prior 0.5 × b × last net + 0.5 × (roster impact − mean), against each season's final net rating): NBA 2012–2026, 450 team-seasons, RMSE 3.030 without ages, 2.971 with the hand-set step, 2.987 with the fitted curve; WNBA 2010–2026, 190 team-seasons, 3.933, 3.886, 3.911. On the NBA 2027 preseason the ages move each team's roster impact by a standard deviation of 1.3 points per 100 (−2.8 to +2.1).</p>\n<span class=\"src\">scripts/bb_bio.py · analytics/bio.py</span>\n\n<h3>Valuation v2</h3>\n<p>Four season slots from now (the rest of this season, then full seasons; in the offseason four full seasons), discounted 0.9 a season: <code>value = Σ 0.9<sup>k</sup> × S<sub>k</sub> × A<sub>k</sub> × G<sub>k</sub> × minutes × (r<sub>k</sub> − R) × pace / 48 / 100 / points per win</code>. <code>r<sub>0</sub></code> is the rest-of-season HPM of the trade simulator; <code>r<sub>k</sub></code> adds the fitted ageing step for each season passed. Minutes come from the team's depth chart. Availability <code>A</code> is the share of team games played over two seasons, regressed to the league mean with 40 pseudo-games; the current slot also takes out the games the injury report rules the player out of (to ESPN's return date, else 10 games for \"Out\", 1 for day-to-day). Survival <code>S</code>, the chance the player is still playing, is a logistic regression on age, age², HPM and log minutes, fitted on every pair of consecutive seasons. Future slots are floored at replacement (a player below it stops being played); the current one is not.</p>\n<p>The ageing curve is the delta method: the average change in HPM between consecutive seasons at each age for players with 500+ minutes in both, weighted by the harmonic mean of the two seasons' minutes, shrunk towards zero (10,000 pseudo-minutes) and smoothed over neighbouring ages. It is not centred: HPM is zero-mean each season and continuing players' measured HPM does rise on average, so the raw change is the unbiased forecast. The band (10th–90th percentile) is a Monte Carlo of 400 draws: a persistent rate error with variance s1² − τ² (scaled up for players with less than 1,500 minutes of information), a yearly drift τ, a lognormal minutes spread (the fitted year-to-year spread of minutes a game) and Bernoulli survival each season. s1 and s2 are the spreads of next season's and the season after's HPM around the ageing path, so the band describes what our own model will measure. VORP at position measures from the position's replacement level: the mean rate of that position's next tier of playing time after the league's rotations (ranked by minutes, so small-sample rates do not select themselves).</p>\n<ul><li>NBA: 7,623 pairs; change at 21 +0.48, 25 +0.14, 29 -0.01, 33 -0.29, 35 -0.33; one-season-ahead spread 1.50, two seasons 1.83, drift 1.04; survival log-loss 0.328 against 0.433 for the base rate (11,332 player-seasons); availability 79 %.</li><li>WNBA: 1,208 pairs; change at 21 +0.35, 25 +0.07, 29 -0.20, 33 -0.12, 35 -0.31; one-season-ahead spread 1.96, two seasons 2.21, drift 1.03; survival log-loss 0.441 against 0.504 for the base rate (2,609 player-seasons); availability 92 %.</li></ul>\n<span class=\"src\">analytics/valuation.py · data/&lt;L&gt;/&lt;S&gt;/valuation.json</span>\n\n<h3>Transactions and trade ratings</h3>\n<p>ESPN's transactions endpoint gives one row per team per day in free text. The site splits each row into sentences, types each by its verb (trade, signing, release, waiver claim, contract, injury list, G League, discipline, staff), and reads the players named after position tags (G, F, C, G/F, Gs, Fs, …) and the draft picks (\"a 2027 second-round pick\", \"four second-round picks\", \"the 22nd overall pick\", \"a 2028 first and second-round pick\"). Names are matched to our player ids with accents, apostrophes and suffixes normalised and, for ESPN's typos, a close spelling only when the team agrees; names we cannot match are listed, never guessed. Two teams' trade sentences form one deal when they name each other within a day (or a player crosses between them and one names the other); a group never holds one team on two different days, so a deadline's successive trades between the same clubs stay separate. Pick swaps, draft considerations and cash are noted and valued at zero.</p>\n<p>Each side is valued three ways in four-season WAR. <strong>At the time</strong>, with no hindsight: the player's last completed season's HPM plus the fitted ageing step, shrunk towards replacement with 250 pseudo-minutes; minutes from the player's games before the date (half-life 12 games); the receiving team's games left; availability and survival as above. <strong>Realised since</strong>: for each game for the new team after the date, (that season's HPM − replacement) × the player's possessions / 100 / points per win, weighted 0.9 a season after the trade's season. <strong>Today's view</strong>: realised plus today's valuation of the seasons left in the trade's window while the player is still on that team (a player since moved on or released adds nothing more). A side's grade is the share of the deal's value it received (A at least 65 %, B 55 %, C 45–55 %, D 35 %, F below; \"minor\" under 0.5 WAR). The league table sums each team's net.</p>\n<p>The pick-value curve (analytics/picks.py): every pick of the 27 NBA drafts from 1996 to 2022 (1,601 picks; WNBA: the six drafts from 2018 to 2023), matched to our players by the athlete records' draft slot, else ESPN's draft lists by id or name; its WAR over the drafted player's first four seasons (the rookie-scale years, the same four-season window as a player's value; each season floored at zero, discounted 0.9), a pick who never played counting zero. A Gaussian kernel that widens down the draft, made non-increasing, gives the expected value by slot (No. 1 about 11.8 WAR, No. 10 6.3, No. 30 2.7, No. 60 0.7), with a band from bootstrap resamples of whole drafts. Validated walk-forward: each draft from 2011 to 2022 predicted only from drafts at least five years older; the curve family was chosen on the 1996-2010 drafts. A traded pick is the curve over its original owner's slot distribution: this season from the season simulation (the lottery, then the playoff teams in reverse order; the second round by record), later drafts from a regression of win % on win % k seasons earlier, discounted 0.9 a season to its first season; \"at the time\" uses only the standings of the last season completed before the trade. Top-N protections convey outside the top N, else roll a year and then convey unprotected (our assumption); \"conditional\" with no terms counts half; a swap is the expected gain of taking the better pick. A used pick is the player it became, valued from its slot until he has played about 1,500 minutes; a draft-rights player named with his slot is that player, not a second asset. Before October 2026 the curve used the draft lists' ids at face value, found few of the players, and valued the No. 1 pick at 3.9 WAR.</p>\n<span class=\"src\">analytics/moves.py · data/&lt;L&gt;/&lt;S&gt;/transactions.json, deals.json</span>\n\n<h3>Fantasy</h3>\n<p>Per game: per-minute rates from the impact model's projections (this season and last, recent games weighted with a 60-game half-life, shrunk to the position with 250 pseudo-minutes) × minutes from the depth chart rebuilt without the players the injury report rules out on that day (their minutes go to the next players up) × the opponent's pace over the league's × the opponent's category factor (what it allows per 100 possessions against the league, this season plus half-weighted last season, shrunk with 20 team-games) × the rest factor (minutes and chance of playing by days of rest, fitted on the three previous seasons). While a rotation player is out, the team's shot attempts, free throws, assists, turnovers and rebounds per minute stay at the healthy team's, redistributed to the active players in proportion to their own rates. The line is then blended with the player's season-to-date line, weight 0.5 × min(1, games / 20) from the player's third game. Rest of season and the next two fantasy weeks (Monday–Sunday) sum the schedule with the chance of playing (availability × rest; zero while ruled out; 0.6 for a day-to-day player's next game).</p>\n<p>Formats are computed on the page: 9-category z-scores against the top 156 players (FG% and FT% weighted by attempts, turnovers negative, any category punted), or points with editable weights (the presets are ours). Tiers break where the gap to the next player exceeds 1.6 times the median gap. Value over replacement uses the 48th guard, 48th forward and 24th centre (12 teams). Without ownership data, waiver targets are players outside our season-start top 150 who rank inside it now (and drops the reverse). Buy low / sell high is shooting luck in points a game: points per shot against the shot model's expected points per shot plus the player's own shot-making over the two previous seasons (shrunk with 250 pseudo-shots), times shots a game, plus free throws against the player's previous percentage.</p>\n<p>Walk-forward check (<code>scripts/bb_fantasy_backtest.py</code>): at weekly checkpoints of five completed seasons, projections from games before the checkpoint only, scored in standard points. The blend weight and the availability term were chosen on WNBA 2023–2025 (blend 0, 0.3, 0.5, 0.7); every NBA season is out of sample for those choices. Baselines: the season-to-date average (last season's under three games) and last season's average. Mean absolute error (ours / season to date / last season) and Spearman rank correlation:</p>\n<table class=\"wc-table\"><thead><tr><th>League and horizon</th><th>Ours</th><th>Season to date</th><th>Last season</th><th>Rank correlation</th><th>n</th></tr></thead><tbody><tr><td>NBA Next 7 days, per game played</td><td>9.90</td><td>9.96</td><td>10.69</td><td>0.776 / 0.768 / 0.683</td><td>107,931</td></tr><tr><td>NBA Next 7 days, total (missed games count)</td><td>24.93</td><td>25.05</td><td>26.99</td><td>— / — / —</td><td>44,655</td></tr><tr><td>NBA Rest of season, per game</td><td>4.28</td><td>4.69</td><td>5.59</td><td>0.846 / 0.837 / 0.752</td><td>39,563</td></tr><tr><td>WNBA Next 7 days, per game played</td><td>8.92</td><td>8.96</td><td>9.69</td><td>0.758 / 0.751 / 0.658</td><td>19,559</td></tr><tr><td>WNBA Next 7 days, total (missed games count)</td><td>17.13</td><td>17.13</td><td>18.95</td><td>— / — / —</td><td>8,948</td></tr><tr><td>WNBA Rest of season, per game</td><td>4.02</td><td>4.27</td><td>5.42</td><td>0.857 / 0.849 / 0.747</td><td>6,856</td></tr></tbody></table>\n<span class=\"src\">analytics/fantasy.py · research/fantasy_backtest.py · data/&lt;L&gt;/&lt;S&gt;/fantasy.json, data/&lt;L&gt;/fantasy_backtest.json</span>\n</section>\n\n<section id=\"m-limitations\">\n<h2>Limitations</h2>\n<ul>\n<li>Rebuilt lineups. ESPN has no on-floor lineups, so they are rebuilt from substitutions, box-score starters and who acts in each period. The rebuild can go wrong in several ways: when a substitution is missing or logged out of order, when a player is on the floor for a whole period without recording an event, and when several changes are logged at the same clock. Repairs pick the most plausible absentee, which can be the wrong player. Box minutes are whole minutes, so the minutes check cannot see errors smaller than about 30 s, and stints without five a side are left out of RAPM.<span class=\"src\">oddsmarkets/basketball/pbp.py</span></li>\n<li>Possession rules. Possessions follow rules, not a possession marker. Held balls, team rebounds, and free throws for technicals, flagrants and away-from-the-play fouls are handled explicitly, but an unusual sequence can split or merge a possession (counted as end \"other\"). Where the parser's possessions are unavailable, win probability falls back to inferring possession from the play text.<span class=\"src\">oddsmarkets/basketball/pbp.py</span><span class=\"src\">oddsmarkets/basketball/models/winprob.py</span></li>\n<li>No tracking data. There is no defender distance, closeout speed, shot clock, dribble count or touch time. xPTS knows only where the shot was taken, how (the shot type ESPN records) and in what game context. Its \"shot-making\" therefore includes the effect of how well a shot was contested, and a defence's points allowed over expected is partly luck and partly contests the data cannot see. A block is an outcome, not a feature.<span class=\"src\">oddsmarkets/basketball/models/shots.py</span></li>\n<li>ESPN coordinates.\n<ul>\n<li>Positions are whole feet, and the rim's position (y = 0.75) was fitted, with a mean error of 0.4 ft against the distances in the play text.</li>\n<li>Plays without a location carry a sentinel value and are dropped.</li>\n<li>Zones follow ESPN's attempt value rather than the geometry, and agreement between the two is reported per game.</li>\n<li>The corner-three rule (y ≤ 8.75 ft and |x| ≥ 20 ft) approximates the painted line.</li>\n<li>Heaves from the far half carry coordinates up to y = 75.</li>\n</ul><span class=\"src\">oddsmarkets/basketball/pbp.py</span></li>\n<li>ESPN data quirks.\n<ul>\n<li>2017-18 team lines are shifted by a column, and scoring plays can carry a zero score value; both are corrected.</li>\n<li>Injuries in a game summary are today's, so they are kept only for games not yet played.</li>\n<li>The DraftKings line is whatever ESPN shows when the game is fetched.</li>\n<li>Plus-minus is missing before about 2007.</li>\n<li>Some box scores are empty: every player is listed with no minutes or statistics. That is about 330 team-games a season in the NBA from 2013 to 2018 (mostly Chicago and New Orleans) and many WNBA games from 2002 to 2005, and fetching them again returns the same zeros. These games are left out of player statistics and box impact; their scores still count in standings, team ratings and points.</li>\n</ul><span class=\"src\">oddsmarkets/basketball/sources/espn.py</span></li>\n<li>In-sample xPTS and box impact. The shot model is fitted on the same season it scores, and the box-impact model is pooled over every play-by-play season, including the current one. Both measure players against their league, not out of sample.<span class=\"src\">oddsmarkets/basketball/models/shots.py</span><span class=\"src\">oddsmarkets/basketball/models/impact.py</span></li>\n<li>Small WNBA samples. A WNBA season is 44 games for each of 15 teams, so team ratings, RAPM and lineup numbers are noisier, which is why the ratings use a shorter half-life and lighter ridge and the season simulation a larger drift. Box scores and play-by-play exist only from 1997 and about 2017 respectively. The win-probability model is trained on up to three earlier seasons, and the award weights need three past winners in the pool, so WNBA fits lean more on their defaults.<span class=\"src\">oddsmarkets/basketball/models/ratings.py</span><span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span></li>\n<li>Award markets are thin. Award fields are long and quoted on few runners, so the thin-market rule often withholds them. The award model sees only box, impact, WPA and team-win features. It does not see narrative, voter fatigue or injuries before they show up in games played. The 65-game projection assumes a player keeps the current rate of qualifying games, and the exceptions in the rule are not modelled.<span class=\"src\">oddsmarkets/basketball/sources/markets.py</span><span class=\"src\">oddsmarkets/basketball/models/awards.py</span></li>\n<li>Season-simulation simplifications.\n<ul>\n<li>Playoff games use end-of-season strengths and home court only, with no rest or travel.</li>\n<li>Draft-pick trades and protections are ignored.</li>\n<li>The NBA Cup knockout bracket is not simulated: its games count as regular-season games, and the Cup winner is shown from the markets only.</li>\n<li>Historical formats are approximate where marked unverified, and the WNBA's 2016-2021 single-game rounds are treated as a plain bracket.</li>\n</ul><span class=\"src\">oddsmarkets/basketball/models/season_sim.py</span><span class=\"src\">oddsmarkets/basketball/models/config.py</span></li>\n<li>Game-model scope.\n<ul>\n<li>sigma is one number per league, so it does not depend on pace or on the size of the spread.</li>\n<li>Travel uses fixed arena coordinates and standard UTC offsets, not daylight-saving time.</li>\n<li>The injury term is used only when the build supplies the list of missing players.</li>\n<li>Until enough history is on disk, the coefficients are the hand-set defaults.</li>\n</ul><span class=\"src\">oddsmarkets/basketball/models/game.py</span></li>\n<li>Win-probability scope. The model has no fouls to give, bonus, timeouts or overtime-specific terms beyond the time left in the period, and ESPN's own probabilities are shown only for comparison.<span class=\"src\">oddsmarkets/basketball/models/winprob.py</span></li>\n<li>Elo history. Elo starts in 1997 with every team at 1505. It knows nothing about rosters, so it reacts to trades and injuries only through results.<span class=\"src\">oddsmarkets/basketball/models/elo.py</span></li>\n<li>Hand-set pieces. The aging curve, the award defaults, the WPA credit shares and the replacement level are set by hand, not fitted.<span class=\"src\">oddsmarkets/basketball/models/impact.py</span><span class=\"src\">oddsmarkets/basketball/models/awards.py</span><span class=\"src\">oddsmarkets/basketball/models/winprob.py</span></li>\n</ul>\n</section>\n";

/* How the pages themselves compute what they show (constants from this site's JS). */
const SITE_HTML = '<section id="m-site"><h2>How the pages compute what they show</h2>' +
  '<p>Almost every number on the site is computed by the Python build and read from the payloads. A few are computed in the browser from those payloads:</p><ul>' +
  '<li><strong>Percentiles</strong> come from the payloads. A league percentile ranks a player against every qualified player that season (100 = best, lower-is-better metrics already flipped). A position-pool percentile ranks the player only against guards, forwards or centres. Players below the minutes floor are shown with their raw values and no percentile.</li>' +
  '<li><strong>The lab</strong> can shrink a player-season rate towards the median of the same position pool (among the players on screen) with a prior of 300 minutes: (minutes × rate + 300 × median) / (minutes + 300). Counts (games, minutes) are never shrunk. Labelled players are the eight with the largest sum of standard scores on both axes in the better direction and the four with the smallest; the ranked table uses the same score. <span class="src">docs/hardwood/assets/js/lab.js SHRINK_K</span></li>' +
  '<li><strong>Shot charts</strong> colour each cell or zone by points per shot minus the league\'s points per shot from the same place, on a scale clipped at ±0.4 (cells) or ±0.25 (zones); cell size is the square root of the number of shots. On team pages the defensive map is mirrored so that red always means good for the team shown. The court is drawn in feet with the rim at (0, 0): 16 ft lane, 4 ft restricted area, 6 ft free-throw circle, three-point arc 23.75 ft (NBA) or 22.15 ft (WNBA) with 22 ft corners, baseline at y = −5.25.</li>' +
  '<li><strong>Compare</strong> counts a metric as won when one side\'s percentile is higher; the verdict lists the three largest percentile gaps each way. When both players are in the same position pool and season, position-pool percentiles are compared; otherwise league percentiles, each against its own season. The head to head uses the games that appear in both players\' logs.</li>' +
  '<li><strong>Leaders</strong> rank any catalogue metric with games and minutes floors; the basis switch moves between the per-game, per-36, per-100 and total versions of a stat where the catalogue carries them.</li>' +
  '<li><strong>Award races</strong> show the model probability, the market\'s de-vigged number matched by player id (or by name with accents and punctuation removed), and the difference, model minus market in percentage points.</li>' +
  '<li><strong>Calibration</strong> reliability bins show ±2 binomial standard errors at the bin\'s mean forecast, sqrt(p(1−p)/n); the "skill v base rate" column is 1 − log-loss / H, where H is the log-loss of always forecasting the home win rate.</li></ul></section>';

function renderMethodology(el, params) {
  const want = (params.rest || [])[0] || '';
  const tmp = document.createElement('div');
  tmp.innerHTML = METHOD_HTML + SITE_HTML;
  const secs = Array.prototype.slice.call(tmp.querySelectorAll('section[id]')).map(s => {
    const h2 = s.querySelector('h2');
    const title = h2 ? h2.textContent : s.id;
    if (h2) h2.parentNode.removeChild(h2);
    return { id: s.id.replace(/^m-/, ''), title: title, html: s.innerHTML };
  });
  const L = (HW.state && HW.state.league) || 'nba';
  const toc = '<div class="doc-toc"><div class="doc-toc-head">Methodology</div><ol>' + secs.map(s => '<li><a href="#/methodology/' + esc(s.id) + '" data-target="method-' + esc(s.id) + '">' + esc(s.title) + '</a></li>').join('') +
    '</ol><div class="doc-toc-head" style="margin-top:10px">See also</div><ol><li><a href="#/glossary">Glossary</a></li><li><a href="#/' + L + '/calibration">Calibration</a></li><li><a href="#/disclaimer">Disclaimer and terms</a></li></ol></div>';
  const idx = HW.index ? (HW.index() || {}) : {};
  const intro = '<div class="card"><div class="card-header">Methodology <span class="card-sub">Where the data comes from, how every model works, and where it is wrong. Written for a numerate fan; every constant is the one in the code, and each paragraph names the file it comes from.</span></div>' +
    '<div class="doc-meta">' + secs.length + ' sections · NBA and WNBA values side by side where they differ' + (idx.updated_at ? ' · site updated ' + esc(HW.fmtStamp(idx.updated_at)) : '') + '</div></div>';
  el.innerHTML = '<div class="doc">' + toc + '<div class="doc-body">' + intro + secs.map((s, i) => '<div class="card" id="method-' + esc(s.id) + '"><div class="card-header">' + (i + 1) + '. ' + esc(s.title) +
    ' <a class="doc-anchor" href="#/methodology/' + esc(s.id) + '" title="Link to this section">#</a></div><div class="pad">' + s.html + '</div></div>').join('') + '</div></div>';
  el.querySelectorAll('.doc-toc a[data-target]').forEach(a => a.addEventListener('click', ev => {
    ev.preventDefault();
    const t = document.getElementById(a.dataset.target);
    if (t) t.scrollIntoView({ block: 'start' });
    history.replaceState(null, '', a.getAttribute('href'));
  }));
  if (want) { const t = document.getElementById('method-' + want.replace(/^m-/, '')); if (t) setTimeout(() => t.scrollIntoView({ block: 'start' }), 0); }
}

HW.route('glossary', renderGlossary);
HW.route('methodology', renderMethodology);
})(window.HW);
